import { useState, useMemo, useEffect, useRef } from 'react'
import { CheckMark } from '../components/Icons'
import { recordInterviewSessionMastery } from '../utils/progress.js'
import { toggleBookmark, isBookmarked, getBookmarks } from '../utils/bookmarks.js'

const QUESTIONS = [
  // ─── ML System Design ────────────────────────────────────────────────────
  { id: 1,  cat: 'System Design', company: 'Meta',    level: 'Senior',   q: 'Design a feed ranking system for a social network with 1B users.', framework: ['Problem framing: relevance? engagement? diversity?', 'Data: user events, item metadata, social graph', 'Features: user–item interaction, freshness, social signals', 'Model: two-stage (retrieval → ranking), GBDT or neural ranker', 'Serving: <100ms P99, feature store for online features', 'Monitoring: CTR, dwell time, diversity metrics, position bias'], whatsTested: 'Whether you know to separate retrieval from ranking, and whether you think about latency, monitoring, and position bias — not just the model itself.', antiPattern: 'Jumping straight to "I\'d train a neural network on all user interactions." A one-stage model at 1B users scale is a serving latency failure. The interviewer is listening for two-stage architecture and production constraints before model choice.' },
  { id: 2,  cat: 'System Design', company: 'Spotify', level: 'Senior',   q: 'Design a music recommendation system that personalises the home screen.', framework: ['Candidate generation: collaborative filtering + content-based', 'Two-tower model: user embedding + track embedding', 'Negative sampling: in-batch vs hard negatives', 'Freshness: re-rank for new releases, mood signals', 'A/B testing: metric choice (stream rate vs skip rate)', 'Cold start: popularity + genre for new users'], whatsTested: 'Whether you address cold start explicitly and whether you choose metrics that reflect user value (stream rate, completion) rather than vanity metrics (clicks).', antiPattern: 'Proposing only collaborative filtering without addressing cold start. CF fails for new users and new tracks — not mentioning a content-based fallback signals you haven\'t thought past the warm-state case.' },
  { id: 3,  cat: 'System Design', company: 'Airbnb', level: 'Senior',   q: 'Design a search ranking system for property listings.', framework: ['Query understanding: location, dates, guests, price range', 'Candidate retrieval: ANN on listing embeddings', 'Ranking: LTR model (ListNet/LambdaMART)', 'Features: listing quality, host response rate, price competitiveness, user history', 'Exploration vs exploitation: ε-greedy or UCB', 'Business constraints: host fairness, availability filtering'], whatsTested: 'Whether you account for the two-sided marketplace dynamic (host fairness, availability) and whether you distinguish retrieval from ranking.', antiPattern: 'Describing a single model that takes a query and scores all listings. At scale this is a latency failure. Also: ignoring business constraints like host fairness — Airbnb explicitly tests whether candidates think beyond pure relevance.' },
  { id: 4,  cat: 'System Design', company: 'Uber',    level: 'Mid',      q: 'Design a fraud detection system for payment transactions.', framework: ['Real-time constraints: <50ms decision latency', 'Features: transaction amount, velocity, device fingerprint, geo-velocity', 'Model: GBDT for tabular, threshold tuning for precision vs recall', 'Class imbalance: SMOTE? Cost-sensitive learning? Both are wrong. Threshold tuning.', 'Feedback loop: confirmed fraud labels, dispute resolution lag', 'Monitoring: fraud rate, false positive rate, chargeback rate'], whatsTested: 'Whether you know that class imbalance in fraud is solved primarily by threshold tuning (not SMOTE), and whether you think about the label delay problem.', antiPattern: 'Saying "I\'d use SMOTE to handle the class imbalance." SMOTE can help in narrow cases but the real lever is threshold calibration based on cost asymmetry. Proposing SMOTE as the primary imbalance fix signals shallow familiarity with production fraud systems.' },
  { id: 5,  cat: 'System Design', company: 'Google', level: 'Staff',    q: 'Design an ML platform for a company with 500 ML engineers.', framework: ['Feature store: offline (Hive/BQ) + online (Redis/Bigtable)', 'Training: managed jobs, experiment tracking (MLflow), hyperparameter tuning', 'Model registry: versioning, lineage, A/B routing', 'Serving: low-latency inference service, batch scoring pipeline', 'Monitoring: data quality, model performance, drift detection', 'Governance: feature sharing, model cards, access control'], whatsTested: 'Whether you think about the platform as a product for internal users (ML engineers), with governance, discoverability, and reducing duplication — not just infrastructure.', antiPattern: 'Listing infrastructure components without discussing the human coordination problem. A platform for 500 engineers that doesn\'t address feature sharing, model cards, and access control will have 500 redundant feature pipelines within a year.' },
  { id: 6,  cat: 'System Design', company: 'Netflix', level: 'Senior',   q: 'Design an A/B testing platform for ML model evaluation.', framework: ['Randomisation unit: user? session? item? (pick wrong → bias)', 'Metric selection: guardrail metrics vs success metrics', 'Sample size calculation: power, MDE, significance level', 'Novelty effect: burn-in period before measuring', 'Interaction effects: overlapping experiments', 'Analysis: t-test, delta method for ratio metrics, CUPED for variance reduction'], whatsTested: 'Whether you identify randomisation unit as the critical design decision, and whether you mention guardrail metrics and novelty effect — not just the mechanics of running a t-test.', antiPattern: 'Jumping to "run a t-test and check p < 0.05." The platform design question is really about: what do you randomize on, how do you handle overlapping experiments, and what guardrails prevent shipping harmful changes. The statistical test is the easy part.' },

  // ─── Feature Engineering ─────────────────────────────────────────────────
  { id: 7,  cat: 'Features', company: 'Any',     level: 'Mid',      q: 'What is training-serving skew and how do you detect it?', answer: 'Training-serving skew is when features computed at training time have different distributions than at serving time. Causes: different code paths, different null handling, timestamp bugs, data leakage. Detection: log serving features → compare PSI/KS against training distribution. Fix: use a feature store with a single computation path for both.', whatsTested: 'Whether you know that the root cause is almost always two separate code paths, and that the fix is a unified feature store — not just retraining.', antiPattern: '"I\'d periodically retrain to keep the model fresh." Retraining does not fix skew — if the serving pipeline computes features differently than the training pipeline, retraining just trains again on features that don\'t match production.' },
  { id: 8,  cat: 'Features', company: 'Any',     level: 'Mid',      q: 'Explain the difference between online and offline features. When would you use each?', answer: 'Offline features (batch): computed over historical data, updated periodically (hours/days). E.g., user lifetime value, 30-day purchase count. Low latency to compute, stale by design. Online features (real-time): computed on-the-fly at serving time. E.g., current session page views, cart contents. Fresh but expensive. Hybrid: pre-compute aggregates offline, serve from feature store, update streaming.', whatsTested: 'Whether you can articulate the staleness vs freshness tradeoff and describe a hybrid architecture — not just list definitions.', antiPattern: '"Online features are just real-time versions of offline features." They serve different purposes: offline captures history, online captures current context. Conflating them misses why both exist in production systems.' },
  { id: 9,  cat: 'Features', company: 'Meta',    level: 'Senior',   q: 'How would you handle a feature with 40% missing values in production?', answer: 'Depends on the missing mechanism. MCAR: mean/median imputation fine. MAR: impute with conditional mean or model. MNAR (most dangerous): encode missingness as a feature itself (binary indicator), model the missing pattern. Never drop rows in production. Always store the imputation strategy computed at training time (in a feature store or artefact) and apply the same logic at serving. Monitor % missing over time as its own drift signal.', whatsTested: 'Whether you distinguish MCAR/MAR/MNAR and whether you know to treat missing-as-signal for MNAR data — the most dangerous and common production case.', antiPattern: '"I\'d drop rows with missing values." Never acceptable in production inference — you can\'t return no prediction because a feature is null. Also wrong: applying imputation at serving time without first computing the statistics on training data only.' },
  { id: 10, cat: 'Features', company: 'Airbnb',  level: 'Senior',   q: 'Design a feature store for a real-time recommendation system serving 10K QPS.', answer: 'Two layers: (1) Offline store (Hive/BigQuery): historical features, training data generation, batch transforms. (2) Online store (Redis/DynamoDB): pre-computed features for sub-millisecond lookup at serving. Key design: materialise offline → online with a streaming pipeline (Flink/Spark Streaming). TTL per feature type. Single feature computation code used in both layers (Python UDFs or dbt). Monitor feature freshness and null rates in both layers.', whatsTested: 'Whether you design for both training and serving consistency from the start — not just a fast serving cache.', antiPattern: '"I\'d use Redis to cache features at serving time." Caching without a sync pipeline from the offline store means training features and serving features diverge. The hard part isn\'t storing features — it\'s keeping both layers consistent with the same computation logic.' },
  { id: 11, cat: 'Features', company: 'Any',     level: 'Mid',      q: 'What is target encoding and what are its risks?', answer: 'Target encoding replaces a categorical feature with the mean target value for that category. Risk: data leakage if computed on the full dataset before splitting (test labels influence training features). Fix: compute on training fold only (k-fold cross-validation style). Also: apply additive smoothing for low-frequency categories (blend with global mean). Never use in streaming/online settings without careful stale-value management.', whatsTested: 'Whether you immediately identify the leakage risk and know the out-of-fold computation fix — not just what target encoding is.', antiPattern: '"Compute the mean target for each category on the full training set." This leaks test labels into training features. The correct answer is out-of-fold computation — the same rows used to compute the encoding should not be used to train the model on that encoding.' },
  { id: 12, cat: 'Features', company: 'Any',     level: 'Mid',      q: 'How do you handle high-cardinality categorical features?', answer: 'Options by cardinality level: Low (< 20): one-hot. Medium (20–1000): target encoding (with smoothing), embedding layer. High (>1000): hashing trick (FeatureHasher), learned embeddings, frequency-based truncation. For entity IDs (user_id, product_id): always use embeddings in neural models. In tree models: target encoding or frequency encoding. Watch for: cardinality explosion across feature crosses.', whatsTested: 'Whether you pick the right strategy based on cardinality level and model type — not a one-size-fits-all answer.', antiPattern: '"One-hot encode everything." Catastrophic for cardinality > 1000 — it creates sparse matrices that kill tree model performance and produce embedding tables that are too large to fit in memory. The interviewer is checking if you know when one-hot stops being appropriate.' },

  // ─── Model Evaluation ────────────────────────────────────────────────────
  { id: 13, cat: 'Evaluation', company: 'Any',     level: 'Mid',      q: 'When would you use PR-AUC over ROC-AUC?', answer: 'Use PR-AUC when positive class is rare (< 10–15% of data). ROC-AUC can be misleadingly high with class imbalance because it accounts for true negatives, which are abundant and easy to classify. PR-AUC focuses only on the positive class precision-recall tradeoff — better for fraud detection, medical diagnosis, spam filtering. Rule of thumb: if you care about the minority class, use PR-AUC.', whatsTested: 'Whether you understand why ROC-AUC is misleading at high class imbalance — specifically that a high true-negative count inflates AUC without the model doing anything useful on the minority class.', antiPattern: '"ROC-AUC is always the standard metric." It\'s the standard only when classes are roughly balanced. Saying this in a fraud or medical context signals you\'ve memorized a rule without understanding the underlying math.' },
  { id: 14, cat: 'Evaluation', company: 'Uber',    level: 'Senior',   q: 'How do you evaluate a model in shadow mode before promoting to production?', answer: 'Log challenger predictions alongside champion predictions (no user impact). Compare: (1) offline metrics on traffic sample, (2) prediction distribution similarity (KL divergence), (3) latency P50/P99, (4) error rate. Define promotion criteria upfront: e.g., PR-AUC ≥ champion + 2pp, latency ≤ 1.2× champion. Run for sufficient duration (2+ weeks) to cover weekly patterns. Watch for novelty effect if testing on clicked items.', whatsTested: 'Whether you know to define promotion criteria before running shadow mode, and whether you check latency — not just model accuracy.', antiPattern: '"Shadow mode is just logging predictions — if metrics look good, promote." Without pre-defined promotion criteria and a minimum run duration, you\'re making a subjective call on cherry-picked results. The discipline is in the pre-commitment.' },
  { id: 15, cat: 'Evaluation', company: 'Any',     level: 'Mid',      q: 'Explain calibration. When does a model need to be calibrated?', answer: 'A model is calibrated if P(y=1 | score=0.7) ≈ 0.7 in reality. Calibration matters when: (1) scores are used as probabilities for downstream decisions, (2) comparing scores across models, (3) setting business thresholds. Neural networks and boosted trees are often miscalibrated (overconfident). Methods: Platt scaling (logistic regression on scores), isotonic regression (non-parametric). Assess with reliability diagrams and expected calibration error (ECE).', whatsTested: 'Whether you distinguish calibration from discrimination (AUC measures discrimination, not calibration) and whether you know when scores need to be true probabilities.', antiPattern: '"High AUC means the model is well-calibrated." AUC and calibration measure different things. A model can rank positives above negatives perfectly (AUC=1) while outputting wildly wrong probabilities. If you\'re using scores to set thresholds or as inputs to downstream models, miscalibration directly corrupts decisions.' },
  { id: 16, cat: 'Evaluation', company: 'Meta',    level: 'Senior',   q: 'How do you measure the impact of a ranking model change in production?', answer: 'Online A/B test with proper randomisation (user-level to avoid interference). Success metrics: business KPI (revenue, engagement). Guardrail metrics: latency, error rate, diversity. Watch: (1) novelty effect — users click more on novel items initially, (2) position bias — lower positions get fewer clicks regardless of quality (correct with IPW or cascade model), (3) delayed conversions — some outcomes take days/weeks to materialise (use holdout + long experiment window).', whatsTested: 'Whether you name position bias and novelty effect as specific failure modes in ranking A/B tests — not just run a generic experiment.', antiPattern: '"Run an A/B test and check if CTR improves." Ranking experiments are especially tricky: novelty effect inflates early CTR for any change, and position bias means clicks don\'t reflect relevance. Naming these and saying how to handle them is what separates a senior answer from a mid-level one.' },

  // ─── PySpark & Data Engineering ──────────────────────────────────────────
  { id: 17, cat: 'Spark', company: 'Any',     level: 'Mid',      q: 'What causes a shuffle in Spark and why is it expensive?', answer: 'Wide transformations cause shuffles: groupBy, join (sort-merge), repartition, distinct, orderBy. Expensive because: data is serialised, written to disk, sent over the network, and read/deserialised on the other side. Each shuffle = disk write + network transfer + disk read. Minimise shuffles: broadcast joins for small tables, use partitioning hints, cache before multiple shuffles, enable AQE (spark.sql.adaptive.enabled=true).', whatsTested: 'Whether you can name the specific transformations that cause shuffles and explain why the disk+network round-trip is the bottleneck — not just "it\'s slow."', antiPattern: '"Shuffles happen when you use joins." Incomplete — groupBy, distinct, and orderBy also cause shuffles. More importantly, saying only "it\'s slow because of network" without explaining the disk write component misses the full picture interviewers are probing for.' },
  { id: 18, cat: 'Spark', company: 'Meta',    level: 'Senior',   q: 'How do you diagnose and fix data skew in a PySpark job?', answer: 'Diagnose: check Spark UI for tasks with >> median duration in a stage (stragglers). Print key distribution: df.groupBy("key").count().orderBy(desc("count")).show(20). Fixes: (1) Salting: add random suffix to hot key, duplicate join table with all salt values. (2) AQE skew join: spark.sql.adaptive.skewJoin.enabled=true. (3) Broadcast join if the other table is small. (4) repartition("less_skewed_key") before aggregation. Root cause: natural hot keys (e.g., "guest", country="US").', whatsTested: 'Whether you lead with diagnosis (Spark UI + key distribution) before prescribing a fix — and whether you know salting as the primary fix for hot-key skew.', antiPattern: '"I\'d increase the number of partitions." Adding partitions doesn\'t fix skew — the hot key still lands on one partition regardless of how many you have. Diagnosis must come before fix, and the fix must match the root cause.' },
  { id: 19, cat: 'Spark', company: 'Any',     level: 'Mid',      q: 'What is the Catalyst optimizer and what does it do?', answer: 'Catalyst is Spark\'s query optimisation framework. Logical plan → Analysis → Logical optimisation (predicate pushdown, constant folding, projection pruning) → Physical planning (choose sort-merge vs broadcast join) → Code generation (Tungsten: JVM bytecode generation). Key optimisations: pushdown filters before shuffle, eliminate unused columns early, rewrite subqueries. You can inspect: df.explain(True) shows all four plan stages. AQE extends this with runtime statistics.', whatsTested: 'Whether you can walk through the four-stage pipeline and explain predicate pushdown as the highest-impact optimisation in practical terms.', antiPattern: '"Catalyst makes Spark faster automatically." True but useless. The answer the interviewer wants is: it pushes filters down before shuffles (so less data moves over the network), eliminates unused columns early, and chooses join strategies based on table sizes. The practical implication is that you should always filter before joining.' },
  { id: 20, cat: 'Spark', company: 'Uber',    level: 'Senior',   q: 'When would you use a broadcast join vs sort-merge join?', answer: 'Broadcast join: one table fits in executor memory (< autoBroadcastJoinThreshold, default 10MB). No shuffle — broadcaster sends full table to every executor. Set: spark.sql.autoBroadcastJoinThreshold = 500MB for medium tables. Sort-merge join: both tables large → sort both by join key, merge. Full shuffle. Explicit: df1.join(broadcast(df2), "key"). Anti-patterns: broadcasting a table that grows over time (silent failures when it exceeds threshold, falls back to sort-merge).', whatsTested: 'Whether you mention the failure mode: a table that grows past the threshold silently falls back to sort-merge without error, causing unexpected performance degradation.', antiPattern: '"Use broadcast join for small tables, sort-merge for large ones." Correct but incomplete — the trap is that "small" is a moving target. A table that fits in memory today may not fit in 6 months. The production-ready answer includes monitoring the table size and setting the threshold explicitly.' },
  { id: 21, cat: 'Spark', company: 'Any',     level: 'Mid',      q: 'What is the difference between repartition and coalesce?', answer: 'repartition(n): full shuffle, creates exactly n partitions. Use when increasing partitions or when current partitioning is skewed. coalesce(n): no shuffle, combines existing partitions (can only decrease). Use for reducing partitions before write (avoid many small files). Rule of thumb: 128–256 MB per partition for most workloads. After a filter that removes 80% of data: coalesce to avoid writing 5× too many small files.', whatsTested: 'Whether you know coalesce avoids a shuffle and when that matters — and whether you apply this to the common "many small files" production problem.', antiPattern: '"repartition is better because it\'s more flexible." It causes a full shuffle. Using repartition to reduce partitions before a write is wasting cluster resources. The correct choice is coalesce for reduction (no shuffle), repartition only when you need to increase or fix skew.' },
  { id: 22, cat: 'Spark', company: 'Meta',    level: 'Senior',   q: 'How do you optimise a Spark job that reads 10TB of Parquet and runs out of memory?', answer: 'Checklist: (1) Increase shuffle partitions: spark.sql.shuffle.partitions=2000. (2) Enable AQE: adaptive partition coalescing. (3) Push predicates to Parquet reader (partition pruning, column pruning). (4) Increase spark.executor.memory, or add executors. (5) Spill config: spark.sql.shuffle.spill=true with adequate disk. (6) Check for skew: straggler tasks = data skew. (7) Use Delta Lake / partitioned tables to avoid full scan. (8) Increase cores per executor to share JVM overhead.', whatsTested: 'Whether you systematically rule out data skew and partition count before jumping to "add more memory" — because adding memory is the last resort, not the first.', antiPattern: '"I\'d increase executor memory." That\'s step 4 of 8. The most common root causes are too-few shuffle partitions (default 200 is almost always wrong for 10TB) and data skew. Jumping to hardware before checking the plan is a red flag for interviewers.' },

  // ─── Coding / ML Implementation ─────────────────────────────────────────
  { id: 23, cat: 'Coding', company: 'Any',     level: 'Mid',      q: 'Implement gradient descent for linear regression from scratch (numpy).', answer: 'W = np.zeros(X.shape[1]); b = 0\nfor _ in range(epochs):\n    y_hat = X @ W + b\n    loss = np.mean((y_hat - y)**2)\n    dW = (2/n) * X.T @ (y_hat - y)\n    db = (2/n) * np.sum(y_hat - y)\n    W -= lr * dW; b -= lr * db\nKey: vectorise with numpy, don\'t loop over samples. For mini-batch: sample indices before each step.', whatsTested: 'Whether you vectorise the gradient update with matrix operations instead of looping over samples — and whether you can derive the gradient of MSE correctly.', antiPattern: 'Using a Python loop over samples: `for i in range(n): dW += (y_hat[i] - y[i]) * X[i]`. This is O(n) slower than the vectorised form and signals you\'re translating math to code mechanically rather than thinking in matrix operations.' },
  { id: 24, cat: 'Coding', company: 'Any',     level: 'Mid',      q: 'Write a function to compute top-k precision and recall for a recommendation model.', answer: 'def precision_at_k(actual, predicted, k):\n    pred_k = predicted[:k]\n    hits = len(set(actual) & set(pred_k))\n    return hits / k\n\ndef recall_at_k(actual, predicted, k):\n    pred_k = predicted[:k]\n    hits = len(set(actual) & set(pred_k))\n    return hits / len(actual) if actual else 0\n\nNote: Average across users. For NDCG also weight by position.', whatsTested: 'Whether you handle edge cases (empty actual list) and whether you correctly divide by k for precision and by len(actual) for recall — not the same denominator.', antiPattern: 'Using the same denominator for both precision and recall. Precision@K divides by K (how many did you show?). Recall@K divides by len(actual) (how many ground truth positives exist?). Swapping them is wrong and interviewers check for this.' },
  { id: 25, cat: 'Coding', company: 'Any',     level: 'Mid',      q: 'How would you implement feature normalisation that avoids data leakage?', answer: 'Always use sklearn Pipeline:\npipe = Pipeline([\n    ("scaler", StandardScaler()),\n    ("clf", LogisticRegression())\n])\npipe.fit(X_train, y_train)  # scaler fitted only on train\npipe.predict(X_test)        # transform uses train statistics\n\nFor cross-validation: use cross_val_score(pipe, X, y) — Pipeline handles fit/transform correctly within each fold.', whatsTested: 'Whether you immediately reach for Pipeline and explain why — because fitting the scaler on train+test before splitting leaks test distribution statistics into training.', antiPattern: '`scaler.fit(X); X_scaled = scaler.transform(X); X_train, X_test = train_test_split(X_scaled)`. Fitting the scaler on the full dataset before splitting means the scaler has seen the test distribution. Always fit preprocessing inside the Pipeline so it only sees training data.' },

  // ─── Behavioural / Architecture ──────────────────────────────────────────
  { id: 26, cat: 'Architecture', company: 'Any',     level: 'Senior',   q: 'Walk me through how you would debug a model that worked in staging but degrades in production.', answer: '1. Check feature parity: are all features available in prod? Any serving-training skew? 2. Check data volume: are edge cases underrepresented in staging? 3. Check label definition: same labelling logic in both? 4. Feature drift: run PSI on all features. 5. Model confidence distribution: are score distributions matching? 6. Slice analysis: is degradation in a specific segment (device, geo, user cohort)? 7. Check for data pipeline issues: late data, null spikes, schema changes.', whatsTested: 'Whether you lead with feature parity and training-serving skew as the most likely cause — and whether you do slice analysis rather than treating degradation as uniform.', antiPattern: '"I\'d retrain the model on production data." Retraining before diagnosing is a guess. The most common cause of staging-to-production gaps is feature pipeline differences or distribution shift — not a model quality problem. Retraining a model on wrong features produces the same wrong model.' },
  { id: 27, cat: 'Architecture', company: 'Google',  level: 'Staff',    q: 'How do you design an ML system that needs to serve 1M QPS with < 50ms P99 latency?', answer: 'Pre-compute wherever possible: run inference batch offline, cache results. For real-time: model compression (quantisation, distillation), ONNX runtime, GPU batching. Tiered serving: fast retrieval (ANN) → lightweight ranking → complex re-ranking only for top-N. Feature serving: dedicated low-latency feature store (Redis clusters). Model caching: cache predictions for frequent input patterns. Autoscaling: K8s HPA on GPU utilisation. Latency budget: feature lookup 5ms + model inference 20ms + overhead 25ms.', whatsTested: 'Whether you think about pre-computation and tiered serving as the primary levers — not just "add more GPUs."', antiPattern: '"I\'d use a faster model or more hardware." At 1M QPS the bottleneck is usually feature lookup latency and cold-path model execution, not raw model speed. The architecture answer (pre-compute, tier the pipeline, cache frequent inputs) is what the interviewer is looking for — hardware scaling is a fallback, not a design.' },
  { id: 28, cat: 'Architecture', company: 'Spotify', level: 'Senior',   q: 'How do you handle the cold start problem for new users and new items?', answer: 'New users: (1) Ask onboarding questions (genre preferences, artists). (2) Use demographic features if available. (3) Popularity-based recommendations with diversity constraints. (4) UCB/Thompson sampling to explore quickly. New items: (1) Content-based features (audio embeddings, metadata). (2) Publisher/artist popularity as proxy. (3) Promote in exploration buckets. (4) Hybrid model: collaborative for warm items, content-based for cold. Track when items "warm up" and transition strategies.', whatsTested: 'Whether you treat new users and new items as two separate problems with different solutions, and whether you have a strategy to transition from cold to warm.', antiPattern: '"I\'d use popularity-based recommendations for cold start." Popularity alone doesn\'t personalise — it just shows the same content to everyone. The interviewer is checking for content-based fallback for new items and an explicit warmup transition strategy, not just a single fallback rule.' },

  // ─── More System Design ──────────────────────────────────────────────────
  { id: 29, cat: 'System Design', company: 'Uber',    level: 'Senior',   q: 'Design a real-time ETA prediction system for a ride-sharing platform.', framework: ['Input features: origin/dest, time of day, day of week, traffic speed (real-time), historical travel times, surge zone', 'Model: gradient boosted trees → can add neural net for complex spatial patterns', 'Latency: < 100ms — pre-compute common route segments, cache traffic embeddings', 'Accuracy metric: MAE in minutes; business metric: user-facing ETA deviation', 'Calibration: ETAs must be slightly pessimistic (underestimate = cancellations)', 'Monitoring: ETA error per city/hour/route type; alert on systematic bias'], whatsTested: 'Whether you address the asymmetric cost of underestimation vs overestimation and whether you think about segment-level monitoring (city, hour, route type) rather than just global MAE.', antiPattern: '"I\'d optimise for MAE." MAE treats a 5-minute underestimate and overestimate identically. In ride-sharing, underestimating ETA causes cancellations — the loss function should be asymmetric. Optimising symmetric MAE in production creates a model that systematically misleads users.' },
  { id: 30, cat: 'System Design', company: 'Any',     level: 'Mid',      q: 'How would you design a content moderation ML system at scale?', framework: ['Multi-stage: fast binary classifier (< 5ms) → detailed multimodal model for borderline cases', 'Labels: mixture of human review queue, policy violation reports, proactive sampling', 'Precision vs recall: false negatives (missed violations) hurt trust; false positives hurt creators', 'Appeal workflow: human review for appealed decisions, feedback loop to retrain', 'Adversarial robustness: users evade classifiers — monitor evasion patterns', 'Explainability: decisions must be explainable for appeals process'], whatsTested: 'Whether you identify label quality (inter-annotator disagreement) and adversarial evasion as the hardest operational problems — not just model architecture.', antiPattern: '"I\'d train a BERT classifier on labeled violations." The hard part isn\'t the model — it\'s label quality (moderators disagree 15–20% of the time on borderline content) and adversarial adaptation (users learn to evade your classifier). A technically correct model on bad labels produces a bad moderation system.' },
  { id: 31, cat: 'System Design', company: 'Netflix', level: 'Senior',   q: 'Design a personalised notification system (push, email) that maximises engagement without fatiguing users.', framework: ['Two objectives: predict click-through on notification AND predict unsubscribe risk', 'Features: user engagement history, content freshness, time-since-last-notif, day/hour, platform', 'Multi-armed bandit per user for frequency optimisation', 'Budget constraints: cap max notifications per user per day/week', 'A/B test: open rate, click rate, unsubscribe rate, opt-out rate', 'Fatigue signal: decreasing open rate over consecutive notifications for a user'], whatsTested: 'Whether you model both click-through AND unsubscribe risk as separate objectives — optimising only for clicks will drive up fatigue and churn.', antiPattern: '"I\'d build a model to maximise open rate." Optimising open rate alone leads to notification spam — the model learns that certain users always open, and targets them until they unsubscribe. The interviewer is looking for the two-objective framing: engagement AND fatigue simultaneously.' },
  { id: 32, cat: 'System Design', company: 'Amazon',  level: 'Senior',   q: 'Design a product search ranking system for an e-commerce platform.', framework: ['Query understanding: spell correction, synonym expansion, intent classification', 'Retrieval: BM25 + dense retrieval (bi-encoder), combine with RRF fusion', 'Ranking: LambdaMART or pointwise neural ranker on retrieved candidates', 'Features: textual relevance, price competitiveness, seller quality, conversion history', 'Personalisation: user purchase/browse history, category affinity embeddings', 'Business rules: promoted listings, inventory status, sponsored products (separate model)'], whatsTested: 'Whether you separate sponsored/promoted products from organic ranking, and whether you address the retrieval-vs-ranking two-stage architecture.', antiPattern: '"I\'d train a single model that takes a query and scores all products." At Amazon scale this is computationally infeasible and conflates organic relevance with business rules. Promoted products must be handled separately — mixing them into the relevance model creates a system that can\'t be independently tuned or audited.' },
  { id: 33, cat: 'System Design', company: 'Google',  level: 'Staff',    q: 'Design a ML system to detect anomalies in time-series metrics at Google scale (millions of time series).', framework: ['Scale: can\'t train individual models per series — learned representations + meta-learning', 'Approach: N-BEATS or Temporal Fusion Transformer for multi-variate forecasting', 'Anomaly = deviation from forecast beyond learned threshold', 'Seasonality: explicit decomposition (daily, weekly, yearly), or let model learn', 'Alert suppression: correlate anomalies across related metrics before alerting', 'Feedback: operator acknowledge/dismiss feeds label to retrain anomaly threshold'], whatsTested: 'Whether you immediately identify that per-series models don\'t scale, and whether you think about alert fatigue (alert suppression via cross-metric correlation).', antiPattern: '"I\'d train a separate model per time series." At millions of series this is operationally impossible — you can\'t maintain, version, or retrain millions of individual models. The answer is a global model with series-level embeddings or meta-learning.' },

  // ─── More Features ───────────────────────────────────────────────────────
  { id: 34, cat: 'Features', company: 'Any',     level: 'Senior',   q: 'How would you compute features for a streaming pipeline with exactly-once semantics?', answer: 'Use Kafka + Flink with checkpointing. Flink guarantees exactly-once with two-phase commit to state backend (RocksDB). Key design: idempotent aggregations (sum, count with watermark deduplication). Late events: watermark delay (allow up to 2 min late). State cleanup: set TTL on state (e.g., session windows close after 30 min inactivity). Output: sink to Redis with conditional write (only update if event timestamp > stored timestamp). Monitor: checkpoint lag, late event rate, watermark progress.', whatsTested: 'Whether you know that exactly-once requires idempotent writes at the sink and checkpoint-based recovery — not just "use Kafka."', antiPattern: '"Kafka guarantees exactly-once delivery." Kafka provides exactly-once within a Kafka-to-Kafka pipeline with transactions. For a Kafka-to-Redis sink you need idempotent writes with conditional timestamp checks — otherwise a replay after a failure will double-count events.' },
  { id: 35, cat: 'Features', company: 'Airbnb',  level: 'Senior',   q: 'Explain point-in-time correct feature joins and why they matter.', answer: 'Point-in-time correct: when generating training data for an event at time T, use feature values as they existed at time T — not their current values. Why it matters: if you train on "host response rate" computed today, you\'re using information unavailable at prediction time → label leakage. Implementation in SQL: asof join — for each event (entity, event_ts), join to feature table on max(feature_ts) where feature_ts <= event_ts. In Feast/Tecton: built-in via get_historical_features() API with entity_df containing event_timestamps.', whatsTested: 'Whether you connect point-in-time correctness directly to label leakage — and whether you know the SQL implementation (asof join) not just the concept.', antiPattern: '"I\'d join training events to the features table on entity ID." Without a time constraint this pulls the current feature value, not the value at the time of the event. This is one of the most common and damaging forms of label leakage in production ML systems.' },
  { id: 36, cat: 'Features', company: 'Any',     level: 'Mid',      q: 'How do you encode cyclical features like hour of day, day of week?', answer: 'Never use raw integers (0–23 for hours) — the model sees 23 and 0 as far apart but they\'re adjacent. Two approaches: (1) Sin/cos encoding: hour_sin = sin(2π × hour / 24), hour_cos = cos(2π × hour / 24). Preserves cyclical distance in 2D space. Simple, always works. (2) Learned embeddings: embed hour as a lookup table. More flexible, captures asymmetric patterns (rush hour is different from midnight). For tree models: sin/cos is better (no embedding layer). For neural models: either works, embedding often better.', whatsTested: 'Whether you explain why raw integers fail for cyclical features — specifically that the model sees 23 and 0 as numerically far apart — before proposing the fix.', antiPattern: '"I\'d normalise hour to [0, 1] by dividing by 24." Normalisation preserves the same problem: hour 0 maps to 0.0 and hour 23 maps to 0.96, so they still appear far apart to the model even though midnight and 11pm are adjacent.' },
  { id: 37, cat: 'Features', company: 'Meta',    level: 'Senior',   q: 'How do you handle label delay in a real-time fraud detection system?', answer: 'Label delay: a transaction\'s fraud label (chargeback) arrives days/weeks after the event. Problems: (1) Training on recent data has mostly unlabelled examples. (2) Using only "aged" data = stale model on new fraud patterns. Solutions: (1) Delayed labelling window: only train on transactions > 30 days old (labels are complete). Accept staleness. (2) Early labels: use merchant dispute flags (arrive < 24h) as noisy proxy labels. (3) Semi-supervised: use unlabelled recent data with pseudo-labels. (4) Two models: real-time risk score (features only) + delayed fraud model (with labels) for threshold calibration.', whatsTested: 'Whether you frame label delay as a training data problem (not a model problem) and whether you can articulate the staleness-vs-freshness tradeoff explicitly.', antiPattern: '"I\'d train on the most recent data to keep the model fresh." Recent data has incomplete labels — chargebacks haven\'t arrived yet, so recent transactions appear mostly non-fraudulent. Training on this produces a model biased toward predicting no-fraud on new patterns.' },

  // ─── More Evaluation ─────────────────────────────────────────────────────
  { id: 38, cat: 'Evaluation', company: 'Any',     level: 'Senior',   q: 'Explain the difference between MRR, NDCG, and MAP for ranking evaluation.', answer: 'MRR (Mean Reciprocal Rank): 1/rank of first relevant item. Good for queries with one relevant answer (navigation). Ignores items beyond first hit. MAP (Mean Average Precision): average precision at each rank where a relevant item appears, averaged over queries. Weights precision by recall. Treats all relevant items equally. NDCG (Normalized Discounted Cumulative Gain): allows graded relevance (1–5 stars, not just relevant/not). Discounts by log2(rank+1). Best for multi-level relevance. Use NDCG for search/rec with graded relevance; MAP for binary relevance with multiple relevant items; MRR for single-answer tasks.', whatsTested: 'Whether you connect each metric to the specific scenario it was designed for — and whether you know the key limitation of MRR (ignores all hits after the first).', antiPattern: '"NDCG is the best ranking metric." NDCG requires graded relevance labels — if your labels are binary (relevant/not), NDCG and MAP produce equivalent results. Claiming NDCG is universally better signals you know the name without understanding when each metric is appropriate.' },
  { id: 39, cat: 'Evaluation', company: 'Netflix', level: 'Senior',   q: 'How do you handle selection bias when evaluating recommendation systems offline?', answer: 'Selection bias: you only observe outcomes (clicks, plays) for items that were actually shown. Items not shown have no labels — you can\'t know if they\'d have been good. Methods: (1) Inverse Propensity Scoring (IPS): weight observed outcomes by 1/probability of being shown. Requires logging the display probability for every item. (2) Doubly-robust estimation: combine IPS with a reward model. More stable than pure IPS. (3) Interleaving: in production, mix challenger and champion items, infer relative quality from user clicks (no logging requirement). (4) Counterfactual evaluation via causal models. Pure offline evaluation without propensity correction will systematically favour items that are already popular.', whatsTested: 'Whether you name propensity scoring as the core technique and whether you can explain why pure offline evaluation is biased toward popular items.', antiPattern: '"Offline evaluation on held-out data is sufficient." In recommenders it is not — you only have labels for items that were shown. Held-out data from a biased policy evaluates how well the model predicts what the old policy already showed, not what users actually prefer.' },
  { id: 40, cat: 'Evaluation', company: 'Any',     level: 'Mid',      q: 'What is CUPED and when would you use it in an A/B test?', answer: 'CUPED (Controlled-experiment Using Pre-Experiment Data): reduces variance in A/B test metrics by using pre-experiment behaviour as a covariate. Mechanism: Y_adj = Y - θ × (X - E[X]), where X is pre-experiment metric, θ estimated to minimise variance. Effect: same statistical power with 30–50% fewer users, or same users with more power. When to use: metric is noisy (session count, revenue), pre-experiment data is available, metric is stable over time. Don\'t use: short experiment windows (no pre-data), metric is fundamentally new (no baseline). Implemented in LinkedIn\'s TEP, Booking.com\'s experimentation platform, Netflix\'s Experimentation Platform.', whatsTested: 'Whether you can explain the variance reduction mechanism (covariate adjustment) and when the method is applicable versus when it fails.', antiPattern: '"CUPED increases statistical power." True but incomplete — the question is how and when. If you can\'t explain that it removes pre-existing user-level variance (making the A/B groups more comparable), or that it fails when there\'s no stable pre-experiment baseline, you\'re reciting a definition rather than demonstrating understanding.' },

  // ─── More Spark ──────────────────────────────────────────────────────────
  { id: 41, cat: 'Spark', company: 'Any',     level: 'Senior',   q: 'Explain Spark\'s memory model and how to tune it to avoid OOM errors.', answer: 'Spark executor memory: Reserved memory (300MB) + User memory (25% for UDFs etc) + Spark memory (75% split between execution and storage). Execution memory (shuffles, joins, sorts) and storage memory (RDD cache) share a pool. Tuning: spark.executor.memory (total), spark.memory.fraction (default 0.6), spark.memory.storageFraction (default 0.5). OOM fixes: increase executor memory, reduce partition size (more shuffle.partitions), avoid caching large DataFrames, use persist(StorageLevel.DISK_ONLY) instead of cache(), check for data skew (single task holding too much data), reduce broadcast threshold.', whatsTested: 'Whether you know the three-zone memory model and can trace an OOM to its cause — skewed partition? cached DataFrame? insufficient execution pool?', antiPattern: '"I\'d just increase spark.executor.memory." More memory doesn\'t fix a data skew OOM — one task gets all the skewed data regardless of per-executor memory. Diagnosing which zone is exhausted (execution vs storage vs user) is the diagnostic step before any tuning.' },
  { id: 42, cat: 'Spark', company: 'Any',     level: 'Mid',      q: 'What is Adaptive Query Execution (AQE) and what does it fix?', answer: 'AQE (spark.sql.adaptive.enabled=true, default in Spark 3.2+) re-optimises query plans at runtime using actual statistics from completed shuffle stages. Three key optimisations: (1) Dynamic partition coalescing: merges small shuffle partitions post-shuffle (fixes too many small partitions). (2) Skew join handling: splits skewed partitions and replicates the join side. (3) Dynamic join strategy: switches sort-merge to broadcast join if one side turns out small after filtering. Enable: default ON in Spark 3.2+. Tune: spark.sql.adaptive.skewJoin.enabled, spark.sql.adaptive.coalescePartitions.minPartitionSize.', whatsTested: 'Whether you can name all three AQE optimisations and explain that it works by re-planning at runtime after shuffle statistics are available — not just "it makes Spark faster."', antiPattern: '"AQE automatically fixes all Spark performance issues." It fixes three specific problems. It does not fix: data skew that isn\'t a join skew, bad query logic, missing partition pruning, or oversized in-memory caches. Knowing the scope of what AQE does (and doesn\'t) is the senior-level answer.' },
  { id: 43, cat: 'Spark', company: 'Meta',    level: 'Senior',   q: 'How would you write an efficient window function over a 500GB dataset with complex partition keys?', answer: 'Window functions require a shuffle over the partition key — unavoidable. Optimise: (1) Use partitionBy on a high-cardinality, non-skewed key. If using user_id, check for power users (skew). (2) Add an orderBy only when required — ordering within a window is expensive. (3) rowsBetween vs rangeBetween: rowsBetween is faster for most cases. (4) Pre-filter data before windowing — reduce size first. (5) If window results don\'t change often, pre-compute and store. (6) Consider Delta Lake Z-ordering on the partition key to minimise shuffle read. (7) Enable AQE skew handling.', whatsTested: 'Whether you immediately think about skew on the partition key (power users) and whether you know orderBy inside a window is expensive even when partitionBy is fine.', antiPattern: '"Window functions are slow — I\'d avoid them." The question is how to make them efficient, not whether to avoid them. Saying you\'d rewrite it with a groupBy+join is rarely better and often worse. The actionable answer is: check for key skew, pre-filter, and avoid unnecessary orderBy.' },

  // ─── More Architecture ────────────────────────────────────────────────────
  { id: 44, cat: 'Architecture', company: 'Any',     level: 'Senior',   q: 'How do you implement a safe model rollout strategy?', answer: 'Progressive rollout: shadow mode (0% traffic, log predictions) → 1% canary → 5% → 20% → 50% → 100%. At each stage: monitor latency P50/P99, error rate, business metrics, prediction distribution. Automated rollback: define health thresholds, trigger automatic rollback if breached. Feature flags: decouple deployment (code in prod) from rollout (traffic controlled by flag). Rollback strategy: model registry with previous version tagged, rollback deploys previous artifact. Experiment tracking: log which model version served which request for debugging. Do not skip stages for non-trivial changes.', whatsTested: 'Whether you emphasise automated rollback with pre-defined thresholds, and whether you distinguish deployment from rollout via feature flags.', antiPattern: '"Deploy to 10% then 50% then 100% and watch metrics." Without pre-defined rollback thresholds and automated rollback, this is manual monitoring — which fails at 2am on a Sunday. The production answer is: thresholds are set before rollout begins, and the system rolls back automatically if any threshold is breached.' },
  { id: 45, cat: 'Architecture', company: 'Any',     level: 'Mid',      q: 'What is the difference between model drift and data drift? How do you monitor each?', answer: 'Data drift (covariate shift): input feature distributions change. Monitor: PSI, KS test on feature distributions vs training baseline. Alert threshold: PSI > 0.1. Data drift causes model degradation without model changing. Concept drift (label shift): relationship between features and target changes. Harder to detect (labels arrive slowly). Monitor: proxy metrics (prediction distribution), downstream business metrics. Model drift: catch-all term sometimes used for both. Monitoring cadence: data drift daily (fast to compute), concept drift weekly (requires labels). Always monitor both.', whatsTested: 'Whether you clearly separate covariate shift (P(X) changes) from concept drift (P(Y|X) changes) and explain why concept drift is harder to detect.', antiPattern: '"I\'d monitor model performance metrics." That only catches concept drift — and only after labels arrive (days or weeks later). Covariate shift is detectable immediately, before performance degrades, and should be the first monitoring layer. Waiting for performance metrics means you\'re always reacting late.' },
  { id: 46, cat: 'Architecture', company: 'Amazon',  level: 'Staff',    q: 'Design a multi-objective ranking system that balances relevance, diversity, and business metrics.', framework: ['Define objectives: relevance (user utility), diversity (avoid homogeneous results), revenue (sponsored items)', 'Scalarisation: weighted sum of objectives — simple but requires careful weight tuning', 'Post-processing re-ranking: MMR (Maximal Marginal Relevance) for diversity after relevance ranking', 'Constrained optimisation: relevance as primary objective, diversity and revenue as constraints', 'Metrics: NDCG for relevance, ILS (Intra-List Similarity) for diversity, revenue per session', 'A/B test design: multi-metric experiment, watch for trade-offs between objectives'], whatsTested: 'Whether you treat diversity and business metrics as constraints (not objectives) to avoid conflating relevance optimisation with business rule enforcement.', antiPattern: '"I\'d use a weighted sum of relevance + diversity + revenue scores." Scalarisation works but forces you to pick weights upfront — and any weight change requires a retrain. The architecturally cleaner answer is: relevance as the primary optimisation, diversity and revenue as post-ranking constraints enforced in re-ranking without model retraining.' },

  // ─── LLM / GenAI ─────────────────────────────────────────────────────────
  { id: 47, cat: 'Architecture', company: 'Any',     level: 'Senior',   q: 'How would you evaluate an LLM-powered product feature in production?', answer: 'LLM evaluation is harder than classification because outputs are open-ended. Multi-layer approach: (1) Offline eval: hold-out set with human-labelled golden answers, use LLM-as-judge (GPT-4 or claude-3 rating responses 1–5). (2) Online eval: implicit signals (thumbs up/down, follow-up questions, session abandonment, downstream task completion). (3) Regression tests: automated suite of known-good prompt–response pairs, fail build if responses degrade. (4) Red-teaming: adversarial probing for safety, accuracy, and policy violations. Key metrics: response quality, factual accuracy, latency, cost per query, refusal rate.', whatsTested: 'Whether you build a multi-layer evaluation framework (offline + online + regression) rather than relying on a single metric, and whether you mention the biases of LLM-as-judge.', antiPattern: '"I\'d ask GPT-4 to rate the responses." LLM-as-judge has documented biases: it prefers longer answers, prefers its own outputs, and has positional bias. Using it without calibrating against human ratings and without an online behavioral signal layer is not a production evaluation framework.' },
  { id: 48, cat: 'Architecture', company: 'Any',     level: 'Senior',   q: 'Explain RAG (Retrieval-Augmented Generation) and when to use it vs fine-tuning.', answer: 'RAG: at inference time, retrieve relevant documents from a vector store, inject into prompt context, generate response grounded in retrieved content. Fixes: hallucination (grounded in facts), knowledge cutoff (retrieves up-to-date documents), explainability (can cite sources). Fine-tuning: updates model weights on task-specific data. Fixes: style/tone alignment, domain-specific knowledge that doesn\'t fit in context, consistent behaviour patterns. Use RAG when: knowledge base changes frequently, need citations, limited compute. Use fine-tuning when: consistent output format, specific domain jargon, RAG latency is prohibitive. Often both: fine-tune + RAG outperforms either alone.', whatsTested: 'Whether you can articulate the fundamental difference in mechanism (retrieval injects context vs fine-tuning changes weights) and match each to the right use case.', antiPattern: '"Fine-tuning is better because it internalises knowledge." Fine-tuned knowledge becomes stale as facts change and is expensive to update. For dynamic knowledge bases or anything requiring citations, RAG is strictly better. Saying fine-tuning is the general solution signals you haven\'t thought about knowledge update cost.' },
  { id: 49, cat: 'Evaluation', company: 'Any',     level: 'Senior',   q: 'How do you measure and reduce hallucinations in an LLM deployed in production?', answer: 'Measure: (1) Human annotation on sample outputs (gold standard but expensive). (2) Automated: NLI-based fact-checking (claim extraction + entailment model). (3) Self-consistency: sample multiple outputs, measure agreement. Reduce: (1) RAG: ground answers in retrieved facts. (2) System prompt engineering: "answer only with information in the provided documents." (3) Calibrated refusal: model should say "I don\'t know" when uncertain — train/prompt for this. (4) Output confidence: if model gives probability estimates, filter low-confidence claims. (5) Post-processing: fact-checking pipeline before serving response.', whatsTested: 'Whether you separate measurement (how do you know it\'s hallucinating?) from reduction (what architectural choices reduce it?) — and whether you mention calibrated refusal.', antiPattern: '"I\'d use RAG to reduce hallucinations." RAG reduces hallucinations on in-corpus questions but doesn\'t eliminate them — the model can still hallucinate when the retrieved context is ambiguous or absent. Treating RAG as a complete solution rather than a strong mitigation that still requires monitoring is a common overstatement.' },
  { id: 50, cat: 'Coding', company: 'Any',     level: 'Mid',      q: 'Implement a simple cosine similarity search for a vector store (Python, numpy).', answer: 'def cosine_similarity(q, corpus):\n    # q: (d,), corpus: (n, d)\n    q_norm = q / np.linalg.norm(q)\n    corpus_norm = corpus / np.linalg.norm(corpus, axis=1, keepdims=True)\n    return corpus_norm @ q_norm  # (n,)\n\ndef top_k(q, corpus, k=5):\n    scores = cosine_similarity(q, corpus)\n    return np.argsort(scores)[::-1][:k]\n\nFor scale: use FAISS (IndexFlatIP after L2-normalising) for million-scale. Exact search is O(n×d) — fine up to ~100k vectors. Beyond: use HNSW (approximate) for sub-linear query time.', whatsTested: 'Whether you normalise both query and corpus vectors before the dot product (not just compute raw dot product) and whether you mention the scale boundary where exact search breaks down.', antiPattern: 'Computing `np.dot(q, corpus.T)` without normalising. Dot product is not cosine similarity — it\'s magnitude-dependent. Two vectors pointing in the same direction but with different magnitudes will have a high dot product but cosine similarity of 1.0. Always normalise before calling it cosine similarity.' },
  { id: 51, cat: 'System Design', company: 'Any',  level: 'Mid',      q: 'Design a real-time feature pipeline that computes user session features (< 1 min latency).', framework: ['Ingest: Kafka topic per event type (page_view, add_to_cart, purchase)', 'Stream processor: Flink with tumbling/sliding windows (session last 30 min)', 'State: RocksDB (Flink state backend) for per-user session state', 'Output: Redis for serving layer (sub-ms lookup); Kafka for downstream consumers', 'Exactly-once: Flink checkpointing + idempotent Redis writes', 'Monitoring: consumer lag, watermark delay, Redis memory, feature null rate'], whatsTested: 'Whether you choose the right state backend for per-user aggregation and whether you address exactly-once semantics at the sink.', antiPattern: '"I\'d use a Spark Structured Streaming job with Redis." Spark Structured Streaming is micro-batch — latency is 1–30s minimum. For sub-minute feature freshness with per-user session state, Flink is the correct choice. Recommending Spark Streaming for sub-minute latency signals you\'re cargo-culting a familiar tool.' },
  { id: 52, cat: 'Architecture', company: 'Any',  level: 'Staff',    q: 'What are the key differences between ML systems at a 50-person startup vs a 5,000-person company? How does your approach change?', answer: 'Startup: speed > robustness. Ship the simplest model that proves value. Off-the-shelf tools (sklearn, FastAPI, SageMaker managed). One engineer owns end-to-end. Monitoring: manual checks + basic alerting. Tech debt is acceptable if acknowledged. Large company: robustness > speed. Models serve millions, failures cost millions. Custom platform (feature store, model registry, CI/CD). Specialised teams (ML engineers, MLOps, platform). Monitoring: automated, paged, with rollback. Governance: model cards, audit trails, fairness testing. As an engineer: at startup, own everything and move fast; at large company, invest in abstractions and enable other teams. Don\'t bring large-company process to a startup, or startup speed culture to production systems serving 100M users.', whatsTested: 'Whether you adapt your engineering philosophy to context rather than applying one universal standard — and whether you can articulate the transition point where process becomes load-bearing rather than bureaucratic.', antiPattern: '"I\'d always use a proper feature store, model registry, and automated CI/CD." At a 50-person startup this is weeks of infra work before shipping anything. The senior answer is knowing when infrastructure investment pays off (when failures have user-facing consequences at scale) versus when it\'s premature optimisation.' },

  // ─── Statistics & Experimentation ──────────────────────────────────────────
  { id: 53, cat: 'Statistics', company: 'Amazon', level: 'Mid',    q: 'What is Sample Ratio Mismatch (SRM) in A/B testing and how do you detect it?', answer: 'SRM: the observed split between control and treatment doesn\'t match the intended split (e.g., intend 50/50 but see 48/52). Causes: logging bugs (events dropped for one variant), bot traffic hitting one variant, assignment errors, feature rollout logic issues. Detection: chi-square test on assignment counts. If p-value < 0.001 → SRM. Always check SRM before interpreting experiment results — an SRM invalidates the experiment because the groups are no longer comparable. Fix by finding the logging/assignment bug, not by adjusting statistics.', whatsTested: 'Whether you check SRM before reading any metric results, and whether you know SRM invalidates the experiment — not just complicates it.', antiPattern: '"I\'d weight the results to account for the imbalance." You cannot statistically correct for SRM — the groups are no longer randomly assigned, so any comparison is invalid. The fix is to find and fix the logging bug, then re-run the experiment.' },
  { id: 54, cat: 'Statistics', company: 'Any',    level: 'Mid',    q: 'How do you calculate minimum detectable effect (MDE) for an A/B test?', answer: 'MDE = minimum effect size you want to detect with power (1-β) and significance α. Formula: MDE = (z_α/2 + z_β) × σ / sqrt(n/2), where σ is the metric standard deviation. Equivalently, given MDE, compute required n. Key inputs: baseline metric value and variance, desired power (usually 80% or 90%), significance level (α=0.05), traffic split. Practical: use an online calculator or scipy.stats.norm — but more importantly, think about what effect is business-meaningful. A 0.1% conversion lift may be statistically detectable but not worth shipping.', whatsTested: 'Whether you frame MDE as a business decision (what effect would change a product decision?) rather than a purely statistical calculation.', antiPattern: '"I\'d set MDE to whatever effect size is statistically achievable with our traffic." MDE should come from the business: "what is the smallest lift that justifies this engineering investment?" Setting it to the smallest detectable effect rather than the smallest meaningful effect leads to shipping changes that technically reach significance but have no real product impact.' },
  { id: 55, cat: 'Statistics', company: 'Amazon', level: 'Senior', q: 'What is a guardrail metric and how do you choose one?', answer: 'Guardrail metrics: metrics that must not degrade even if the success metric improves. They protect against harmful side effects. Examples: if success metric is clicks, guardrail = page load time, unsubscribe rate. Choosing guardrails: (1) Think about what you\'d be blamed for if it broke. (2) Include at least one user harm metric (unsubscribes, session abandonment). (3) Include one platform health metric (error rate, latency P99). (4) Guardrails should be easier to measure quickly than the primary metric. Rule: if your guardrail is violated, stop the experiment regardless of success metric. Do not cherry-pick guardrails after seeing results.', whatsTested: 'Whether you state explicitly that a guardrail violation stops the experiment regardless of the primary metric, and whether you choose guardrails before running (not after seeing results).', antiPattern: '"I\'d monitor key metrics alongside the primary metric." Monitoring is passive — guardrails are commitments. The discipline is pre-committing to stop conditions. Choosing or adjusting guardrails after seeing results is a form of p-hacking that the interviewer is testing for.' },
  { id: 56, cat: 'Statistics', company: 'Netflix', level: 'Senior', q: 'How do you handle network effects (interference) when running A/B tests in a marketplace or social network?', answer: 'Interference: treatment users affect control users (e.g., driver app on a ride-share platform — surge pricing experiment on drivers changes wait times for all users). Solutions: (1) Cluster/switchback experiments: assign by geographic unit or time windows rather than users. (2) Ego network randomization: assign by user+friends cluster. (3) Bipartite graph randomization: assign supply-side vs demand-side separately. (4) Holdout sets: geographic market-level holdout. (5) Difference-in-differences: if you can find natural divides. Tradeoffs: cluster experiments have lower power (fewer independent units). Always explicitly state your independence assumption and whether it holds.', whatsTested: 'Whether you identify SUTVA violation as the core problem and whether you can name at least one randomisation design that handles it.', antiPattern: '"Standard A/B test with user-level randomisation." In a marketplace or social network, control and treatment users share infrastructure (drivers, inventory, social connections) — user-level randomisation produces contaminated groups. The answer must address the interference directly, not just run a standard experiment.' },
  { id: 57, cat: 'Statistics', company: 'Any',    level: 'Mid',    q: 'Explain the difference between Type I and Type II error and their practical implications in ML.', answer: 'Type I (false positive): reject H0 when it\'s true. In production: ship a change that has no real effect. Rate = α (significance level). Type II (false negative): fail to reject H0 when it\'s false. In production: miss a real improvement. Rate = β; Power = 1-β. Practical ML implications: fraud detection — Type II (miss fraud) more costly than Type I (flag legitimate txn). Medical diagnosis — Type II (miss disease) is life-threatening. Recommendation system — Type I (ship bad feature) wastes engineering. Threshold tuning trades Type I vs Type II directly. Increasing α (e.g., 0.10 instead of 0.05) increases power but also increases false positive rate — only acceptable if Type II error is more costly.', whatsTested: 'Whether you connect Type I/II error to a domain-specific cost asymmetry, not just recite definitions.', antiPattern: '"α = 0.05 is the standard and you should always use it." The threshold should reflect the cost of each error type. In medical screening, missing a disease (Type II) costs far more than a false alarm — using α = 0.05 symmetrically misses this. The correct answer asks: in this domain, which error is more costly, and how does that inform the threshold choice?' },
  { id: 58, cat: 'Statistics', company: 'Uber',   level: 'Senior', q: 'What is the unit of randomization in an A/B test and why does it matter?', answer: 'The unit of randomization determines what you randomize (user, session, device, geographic region, driver). It must match the unit of analysis for valid inference. Problems when mismatched: user-level metric but session-level randomization → same user sees both variants (spillover, variance inflation). Correct approach: randomize at the level where you can reasonably assume independence. For user-facing product features: user_id. For marketplace supply/demand: geo cluster or time. For push notifications: user_id. For search ranking: query session. Wrong choice → variance deflation (spuriously significant results) or inflation (lost power). Always document the randomization unit in experiment design.', whatsTested: 'Whether you explain the consequence of mismatching randomisation and analysis units — specifically that it inflates or deflates variance and invalidates inference.', antiPattern: '"Randomise by user ID." Always. User ID is the right choice for most consumer product features — but in a marketplace (ride-share, delivery) where supply and demand interact, user-level randomisation violates independence. The answer must acknowledge that the right unit depends on interference structure.' },
  { id: 59, cat: 'Statistics', company: 'Any',    level: 'Mid',    q: 'How do you interpret a confidence interval correctly? What are common misinterpretations?', answer: 'Correct: a 95% CI means that if we repeated the experiment many times, 95% of such intervals would contain the true parameter. It does NOT mean: "there is a 95% probability the true value is in this interval" (frequentist — the true value is fixed, not random). Common misinterpretations: (1) "The interval contains the true mean with 95% probability" — wrong framing. (2) "Overlapping CIs means no significant difference" — wrong: two 95% CIs can overlap and still be significantly different (use a two-sample test). (3) "Wider CI = less reliable estimate" — true, but doesn\'t mean wrong. Practical use: look at the entire interval, not just significance — a wide CI with positive lower bound is more useful than a barely significant p-value.', whatsTested: 'Whether you state the frequentist interpretation correctly and whether you know that overlapping CIs do not imply non-significance.', antiPattern: '"There\'s a 95% probability the true value is in this interval." This is the Bayesian credible interval interpretation — not the frequentist confidence interval. Interviewers at companies with rigorous experimentation (Airbnb, Booking.com, Netflix) specifically test for this misinterpretation because it leads to wrong decisions in experiment analysis.' },

  // ─── Trees & Ensembles ──────────────────────────────────────────────────────
  { id: 60, cat: 'Trees & Ensembles', company: 'Any',    level: 'Mid',    q: 'Why does Random Forest reduce variance but not bias? When does it fail?', answer: 'RF reduces variance by averaging many decorrelated trees. Individual trees have high variance (overfit) but low bias on enough depth. Averaging reduces variance: Var(mean) = σ²/n if independent. Decorrelation via feature subsampling prevents correlation between trees (without it, all trees look similar and averaging doesn\'t help much). Bias is unchanged: each tree is trained to fit the data, the average has the same bias as each tree. Fails when: (1) The problem has strong structure that trees can\'t capture (linear relationships need many splits). (2) Features are highly correlated — feature subsampling doesn\'t help as much. (3) Class imbalance — trees split poorly on minority class without cost-sensitive training. (4) Need calibrated probabilities — RF probabilities are often too extreme, need Platt scaling.', whatsTested: 'Whether you can explain why averaging reduces variance (Var(mean) = σ²/n) but not bias (each tree has the same bias), and whether you know the calibration failure mode.', antiPattern: '"Random Forest is better than a single tree because it reduces overfitting." True but shallow. The interviewer wants the mechanism: averaging decorrelated trees reduces variance without changing bias. Not mentioning the decorrelation step (feature subsampling) misses the key reason RF works better than bagged trees.' },
  { id: 61, cat: 'Trees & Ensembles', company: 'Any',    level: 'Mid',    q: 'What is the difference between Gini impurity and entropy as split criteria? Does it matter in practice?', answer: 'Gini impurity: 1 - Σp_i². Entropy (information gain): -Σp_i log(p_i). Both measure class heterogeneity in a node. Gini is computationally cheaper (no log). Entropy is slightly more sensitive to class probability shifts at extreme imbalance. In practice: almost never matters — the trees produced are nearly identical. Decision: use Gini for speed (default in sklearn). Use entropy when you want to interpret information-theoretic meaning in the split. The more important choice is max_depth, min_samples_split, and n_estimators — these dominate model quality.', whatsTested: 'Whether you answer honestly that the choice rarely matters in practice and redirect attention to hyperparameters that actually drive model quality.', antiPattern: '"I\'d use entropy because it\'s more theoretically grounded." Spending interview time debating Gini vs entropy is a signal that you\'re optimising irrelevant details. The correct answer acknowledges it almost never matters and pivots to what does — max_depth, regularisation, early stopping.' },
  { id: 62, cat: 'Trees & Ensembles', company: 'Google', level: 'Senior', q: 'How does XGBoost handle missing values differently from sklearn\'s GradientBoostingClassifier?', answer: 'XGBoost has native missing value handling: during training, for each feature with missing values, it tries both left and right as the default direction and picks whichever reduces loss more. This learned default direction is stored per feature and used at inference. No imputation needed. sklearn GBM: does not have native missing value handling — requires explicit imputation before fitting. In practice: XGBoost\'s approach is usually better for MCAR/MAR missingness because it doesn\'t impose a distributional assumption. For MNAR data (missingness is informative), both approaches can learn the pattern — but adding a binary missingness indicator feature explicitly is still a good practice.', whatsTested: 'Whether you know XGBoost learns a default split direction per feature at training time and stores it for inference — not just "it handles missing values automatically."', antiPattern: '"XGBoost ignores missing values." It doesn\'t — it learns which direction (left or right subtree) is optimal for missing values at each node, then uses that direction at inference time. "Ignores" implies the feature is skipped, which is wrong and would break monotone constraint guarantees.' },
  { id: 63, cat: 'Trees & Ensembles', company: 'Any',    level: 'Senior', q: 'How do learning_rate and n_estimators interact in gradient boosting? What\'s the practical tuning strategy?', answer: 'They have an inverse relationship: lower learning_rate (shrinkage) requires more trees to achieve the same training fit, but typically generalises better. The product learning_rate × n_estimators roughly determines total model capacity. Practical strategy: (1) Set n_estimators large (500–2000) and learning_rate small (0.01–0.05). (2) Use early stopping on a validation set to find optimal n_estimators. (3) Reduce learning_rate further if overfitting, let early stopping find the new optimal n_estimators. Anti-pattern: tuning n_estimators and learning_rate separately via grid search — they\'re coupled, always tune together. XGBoost\'s early_stopping_rounds makes this easy.', whatsTested: 'Whether you know to fix n_estimators with early stopping rather than grid-searching it independently from learning_rate.', antiPattern: '"I\'d grid-search learning_rate ∈ [0.01, 0.1, 1.0] and n_estimators ∈ [100, 300, 500]." These two hyperparameters are coupled — a learning_rate of 0.01 with 300 trees underfits, while 0.1 with 2000 trees overfits. Grid-searching them independently is statistically invalid and wastes compute. Use early stopping to find optimal n_estimators for each learning_rate candidate.' },
  { id: 64, cat: 'Trees & Ensembles', company: 'Meta',   level: 'Senior', q: 'Why is tree-based feature importance unreliable on correlated features? What should you use instead?', answer: 'Tree importance (split count, impurity reduction) is unreliable when features are correlated because: the model can use either feature to make the same split — whichever is seen first in the greedy search gets the credit. Result: both correlated features show artificially low importance, or one randomly dominates. Solutions: (1) Permutation importance: shuffle one feature at a time and measure validation metric drop. More reliable, but still affected by correlation (two correlated features together capture variance, shuffling one doesn\'t fully break the signal). (2) SHAP values: based on Shapley game theory — distributes prediction contribution across features fairly. Handles correlated features better. (3) Drop-column importance: most expensive, most reliable — retrain without each feature.', whatsTested: 'Whether you name SHAP as the theoretically correct solution and can explain why permutation importance is still biased under correlation.', antiPattern: '"I\'d use permutation importance — it\'s more reliable than split-based importance." Permutation importance is more reliable for independent features but still biased under correlation: shuffling one of two correlated features still leaves the other to explain most of the variance. SHAP distributes credit across correlated features using Shapley values, which is the principled solution.' },
  { id: 65, cat: 'Trees & Ensembles', company: 'Any',    level: 'Mid',    q: 'What are the key regularization parameters in XGBoost and what do they control?', answer: 'gamma (min_split_loss): minimum loss reduction to make a further split. Higher = more conservative tree. lambda (L2 on leaf weights): shrinks individual leaf scores. Default=1. Reduces variance. alpha (L1 on leaf weights): sparsity in leaf scores. Useful when many features are irrelevant. max_depth: controls tree complexity directly (depth > 6 usually overfitting). subsample: row subsampling per tree (like RF). colsample_bytree / colsample_bylevel: feature subsampling. Tuning priority: max_depth, n_estimators + learning_rate (most impact) → subsample, colsample (usually 0.7–0.9) → gamma, lambda, alpha (fine-tune). Use early stopping to fix n_estimators, then tune the rest.', whatsTested: 'Whether you know the tuning priority order — max_depth and learning_rate dominate, gamma/lambda/alpha are fine-tuning levers, not first-pass choices.', antiPattern: '"I\'d tune all hyperparameters together with a grid search." With 7+ XGBoost hyperparameters, exhaustive grid search is computationally intractable and misses the interactions between them. The correct approach: set learning_rate + n_estimators (with early stopping) first, then tune tree structure (max_depth, min_child_weight), then subsampling, then regularisation.' },

  // ─── SQL ───────────────────────────────────────────────────────────────────
  { id: 66, cat: 'SQL', company: 'Amazon', level: 'Mid',    q: 'What is the difference between ROW_NUMBER, RANK, and DENSE_RANK? Give a use case for each.', answer: 'ROW_NUMBER: assigns unique sequential integers, no ties. Use: deduplicate — keep one row per user (latest event). RANK: assigns the same rank to ties, then skips numbers (1,1,3,4). Use: "top 3 products by revenue" where you want gaps. DENSE_RANK: same rank for ties, no skipping (1,1,2,3). Use: "rank employees by salary in department" where you want contiguous ranks. Example — dedup latest event per user:\nSELECT * FROM (\n  SELECT *, ROW_NUMBER() OVER (PARTITION BY user_id ORDER BY event_ts DESC) rn\n  FROM events\n) WHERE rn = 1', whatsTested: 'Whether you connect each function to a concrete use case — especially the deduplication pattern with ROW_NUMBER, which appears in almost every data interview.', antiPattern: '"They all assign ranks to rows." True but the question asks for when you\'d use each. The interviewer is checking: do you reach for ROW_NUMBER for deduplication, RANK when tied positions should skip numbers, and DENSE_RANK when they shouldn\'t? Giving only definitions without use cases signals you\'ve memorised without applying.' },
  { id: 67, cat: 'SQL', company: 'Any',    level: 'Mid',    q: 'How would you write a SQL query to compute a 7-day rolling retention rate?', answer: 'Step 1: Find each user\'s first active date. Step 2: For each date, count users who were active on that date AND on date+7.\nWITH first_day AS (\n  SELECT user_id, MIN(DATE(event_ts)) AS cohort_date FROM events GROUP BY 1\n),\nactivity AS (\n  SELECT DISTINCT user_id, DATE(event_ts) AS active_date FROM events\n)\nSELECT\n  fd.cohort_date,\n  COUNT(DISTINCT fd.user_id) AS cohort_size,\n  COUNT(DISTINCT a.user_id) AS retained_d7,\n  ROUND(COUNT(DISTINCT a.user_id) * 1.0 / COUNT(DISTINCT fd.user_id), 3) AS d7_retention\nFROM first_day fd\nLEFT JOIN activity a\n  ON fd.user_id = a.user_id\n  AND a.active_date = fd.cohort_date + INTERVAL \'7 days\'\nGROUP BY 1\nOPTIMISATION: Partition activity table on user_id and date.', whatsTested: 'Whether you use a LEFT JOIN (not INNER JOIN) to include users in the cohort who were not retained, and whether you correctly denominate by cohort_size not total users.', antiPattern: 'Using INNER JOIN instead of LEFT JOIN: `FROM first_day fd JOIN activity a ON...`. This silently drops users who were active on day 0 but not day 7 — those users should count as not retained, not disappear from the query. The retention denominator must be cohort_size, and users with no day-7 activity need NULL/0 in the numerator.' },
  { id: 68, cat: 'SQL', company: 'Amazon', level: 'Mid',    q: 'How do you write a funnel query in SQL (e.g., view → add_to_cart → purchase)?', answer: 'Use conditional counting — count distinct users at each step, in order:\nSELECT\n  COUNT(DISTINCT CASE WHEN event = \'view\' THEN user_id END) AS viewers,\n  COUNT(DISTINCT CASE WHEN event = \'add_to_cart\' THEN user_id END) AS adders,\n  COUNT(DISTINCT CASE WHEN event = \'purchase\' THEN user_id END) AS purchasers,\n  ROUND(COUNT(DISTINCT CASE WHEN event = \'add_to_cart\' THEN user_id END) * 1.0 /\n        NULLIF(COUNT(DISTINCT CASE WHEN event = \'view\' THEN user_id END),0), 3) AS view_to_cart,\n  ROUND(COUNT(DISTINCT CASE WHEN event = \'purchase\' THEN user_id END) * 1.0 /\n        NULLIF(COUNT(DISTINCT CASE WHEN event = \'add_to_cart\' THEN user_id END),0), 3) AS cart_to_purchase\nFROM events\nWHERE event_ts BETWEEN \'2024-01-01\' AND \'2024-01-31\'\nNote: this counts users who did ANY of each event — for strict funnel ordering, use window functions to filter by sequence.', whatsTested: 'Whether you use NULLIF to prevent division-by-zero and whether you note the limitation of unordered counting (users counted at each step regardless of sequence).', antiPattern: 'Dividing without NULLIF: `COUNT(adders) / COUNT(viewers)`. If viewers is 0 for any period, this throws a division-by-zero error. Also: not noting that this query counts users who did each event in any order — a user who purchased before viewing would still be counted. Acknowledging this limitation signals senior-level thinking.' },
  { id: 69, cat: 'SQL', company: 'Uber',   level: 'Senior', q: 'Write a SQL query to compute A/B test lift using only SQL (no Python).', answer: 'SELECT\n  variant,\n  COUNT(DISTINCT user_id) AS users,\n  SUM(converted) AS conversions,\n  ROUND(AVG(converted::float), 4) AS cvr,\n  ROUND(AVG(converted::float) - MIN(AVG(converted::float)) OVER (), 4) AS lift_vs_control,\n  ROUND(STDDEV(converted::float) / SQRT(COUNT(*)), 5) AS std_error\nFROM experiment_log\nWHERE experiment_id = \'exp_123\'\nGROUP BY variant\nFor significance: compute z-score = lift / pooled_std_error. Full significance test in SQL is verbose — better in Python/statsmodels. Key rule: always use user-level aggregation, not event-level, to avoid correlated observations. A single user\'s multiple events are not independent.', whatsTested: 'Whether you aggregate at user level (not event level) and whether you compute standard error correctly — and whether you acknowledge SQL\'s limits for full significance testing.', antiPattern: 'Aggregating at event level: `GROUP BY variant, event_date`. If a user has 10 events, each event is treated as an independent observation — this deflates standard error and produces spuriously significant results. The correct unit of analysis is user_id, not event row.' },
  { id: 70, cat: 'SQL', company: 'Any',    level: 'Mid',    q: 'What is a CTE and when should you use it over a subquery?', answer: 'CTE (Common Table Expression): a named temporary result set defined with WITH. SELECT ... FROM (\n  SELECT ...\n) subq  →  WITH cte AS (SELECT ...) SELECT ... FROM cte\nUse CTE when: (1) You reference the same subquery multiple times (avoid code duplication). (2) You need to chain multiple transformation steps (readability). (3) You\'re using a recursive query (hierarchical data, graph traversal). Use subquery when: the logic is simple and used only once. Performance: in most databases (Postgres, BigQuery, Snowflake), CTEs are not materialised by default — they\'re inlined like subqueries. Exception: some databases materialise CTEs, which can be slower or faster depending on the query.', whatsTested: 'Whether you know that CTEs are not materialised by default in most engines (they\'re syntactic sugar, not a caching mechanism) and whether you can name the recursive CTE use case.', antiPattern: '"CTEs are better than subqueries because they\'re cached." In Postgres, BigQuery, and Snowflake, CTEs are inlined — not cached. Saying they improve performance by caching intermediate results is wrong by default and will fail in live coding at a company with an experienced data engineer on the interview panel.' },

  // ─── Regression ────────────────────────────────────────────────────────────
  { id: 71, cat: 'Regression', company: 'Any',    level: 'Mid',    q: 'What are the Gauss-Markov assumptions? Which one is most commonly violated in practice?', answer: 'Gauss-Markov (for OLS to be BLUE): (1) Linearity in parameters. (2) Random sampling / IID observations. (3) No perfect multicollinearity. (4) Exogeneity: E[ε|X] = 0 (no omitted variable bias). (5) Homoskedasticity: constant error variance. Most commonly violated in practice: (4) Exogeneity — in observational data, there are almost always unmeasured confounders. Fix: instrumental variables, causal inference methods. Second most common: (5) Homoskedasticity — violated in financial data, count data. Fix: robust standard errors (HC3), or use a model with appropriate distributional assumptions (Poisson for counts, Gamma for right-skewed). Normality of errors is NOT a Gauss-Markov assumption — it\'s only needed for exact finite-sample inference.', whatsTested: 'Whether you identify exogeneity (not normality) as the most commonly violated assumption, and whether you correctly state that normality is NOT a Gauss-Markov assumption.', antiPattern: '"The normality of errors assumption is the most commonly violated." This confuses two different theorem requirements. Gauss-Markov doesn\'t require normality — it only requires conditions 1–5 for OLS to be BLUE. Normality is needed for exact t/F statistics in small samples. In large samples, CLT handles it. Saying normality is a Gauss-Markov assumption is a textbook error that interviewers at Amazon/Airbnb will catch.' },
  { id: 72, cat: 'Regression', company: 'Any',    level: 'Mid',    q: 'When would you choose Ridge vs Lasso vs ElasticNet? What does each penalty do geometrically?', answer: 'Ridge (L2): adds λΣβ². Shrinks all coefficients toward zero but never to exactly zero. Best when: many features, all with small effects (dense solution). Geometry: circular constraint — smooth shrinkage. Lasso (L1): adds λΣ|β|. Produces exactly zero coefficients — automatic feature selection. Best when: sparse true model (few important features). Geometry: diamond constraint — corners encourage zeros. ElasticNet (L1+L2): combines both. Best when: grouped correlated features (Lasso arbitrarily picks one; ElasticNet can include all). Practical default: try Ridge first. If you suspect sparse signal, try Lasso. If features are correlated, ElasticNet. Always cross-validate λ. In sklearn: Ridge, Lasso, ElasticNet — all with CV variants (RidgeCV, LassoCV).', whatsTested: 'Whether you explain the geometric intuition (circular vs diamond constraint) and whether you know Lasso fails on grouped correlated features.', antiPattern: '"Lasso is better because it does feature selection." Lasso arbitrarily selects one feature from a correlated group and zeros out the rest — which is wrong when all members of the group carry genuine signal. In high-correlation settings, ElasticNet is strictly better. Recommending Lasso as universally superior signals you\'ve memorised the feature selection property without its failure condition.' },
  { id: 73, cat: 'Regression', company: 'Any',    level: 'Senior', q: 'How do you detect and handle multicollinearity in a regression model?', answer: 'Detection: (1) Correlation matrix: look for pairwise correlations > 0.85. (2) Variance Inflation Factor (VIF): VIF = 1/(1-R²_i) where R²_i is the R² from regressing feature i on all others. VIF > 5–10 indicates multicollinearity. (3) Condition number of X\'TX: > 30 suggests instability. Impact: coefficients become unstable (high variance), standard errors inflate, interpretation is unreliable. Does NOT affect prediction accuracy if the same collinearity exists at serving time. Fixes: (1) Drop one of the correlated pair. (2) PCA on correlated block (dimensionality reduction). (3) Ridge regression — stabilises coefficients under multicollinearity. (4) Collect more data (sometimes reduces variance). Do NOT use Lasso — it arbitrarily picks one feature and drops the rest.', whatsTested: 'Whether you state the critical nuance: multicollinearity hurts interpretability but NOT predictive accuracy — and whether you recommend VIF over just correlation.', antiPattern: '"Multicollinearity makes the model less accurate." It doesn\'t — if the same collinearity structure exists at serving time, predictions are unaffected. What multicollinearity destroys is coefficient interpretability and standard error reliability. Framing it as an accuracy problem leads to unnecessary feature removal that can actually hurt performance.' },
  { id: 74, cat: 'Regression', company: 'Any',    level: 'Mid',    q: 'How do you interpret logistic regression coefficients when features have interaction terms?', answer: 'Without interaction: the coefficient β₁ gives the change in log-odds for a 1-unit increase in x₁, holding all else constant. Exponentiate to get odds ratio: exp(β₁). With interaction term x₁×x₂: the marginal effect of x₁ now depends on x₂. Specifically, the change in log-odds per unit x₁ = β₁ + β₃×x₂. You cannot interpret β₁ alone. Instead: (1) Compute marginal effects at specific x₂ values. (2) Plot the interaction (log-odds as a function of x₁ at different x₂ levels). Practical advice: only add interaction terms when you have a theoretical reason or strong data evidence — they increase model complexity and interpretation burden. With many features and interactions, switch to a tree-based model which captures interactions implicitly.', whatsTested: 'Whether you know the main effect coefficient β₁ is uninterpretable in isolation when an interaction term is present.', antiPattern: '"The coefficient β₁ tells you the effect of x₁ on the outcome, and β₃ tells you the interaction effect." Once an interaction term x₁×x₂ is included, β₁ is only the effect of x₁ when x₂ = 0 — not the average effect of x₁. Interpreting the main effect independently of the interaction is a common and consequential error in analysis reports.' },
  { id: 75, cat: 'Regression', company: 'Amazon', level: 'Senior', q: 'How do you evaluate the quality of residuals in a regression model?', answer: 'Four key diagnostic plots: (1) Residuals vs Fitted: should be a random cloud around zero. Pattern = missed nonlinearity. (2) Q-Q plot: residuals vs normal quantiles. Deviations from line = non-normality (not a Gauss-Markov violation, but affects inference). (3) Scale-Location: sqrt(|residuals|) vs fitted. Funnel shape = heteroskedasticity → use robust SEs. (4) Residuals vs Leverage: Cook\'s distance identifies influential outliers. In production: plot residual distribution on held-out data. If there are systematic biases by time, geography, or user segment, the model needs interaction terms or separate models per segment.', whatsTested: 'Whether you name all four diagnostic plots and connect each to a specific failure mode — and whether you check for systematic segment-level bias in production.', antiPattern: '"I\'d check the R² and RMSE to evaluate residuals." R² and RMSE are scalar summaries — they hide systematic patterns. A model with R²=0.85 can have a funnel-shaped residual pattern (heteroskedasticity) that makes all confidence intervals wrong. Residual plots are irreplaceable; summary statistics are not substitutes.' },

  // ─── More Architecture ─────────────────────────────────────────────────────
  { id: 76, cat: 'Architecture', company: 'Any',   level: 'Senior', q: 'What is label leakage and how is it different from feature leakage?', answer: 'Feature leakage: a feature used at training time is unavailable or calculated differently at serving time. Examples: using the future target to compute a feature (classic); using data from after the event being predicted. Label leakage: the label itself is influenced by data that won\'t be available at prediction time — or the label is misdefined. Example: churn model where label = "cancelled in next 30 days" but you include "customer_support_calls_this_month" which happens BECAUSE of churn. The feature is correlated with the label not causally, but because both are caused by the same underlying event. Fix feature leakage: strict point-in-time joins. Fix label leakage: audit your label definition — ask "could this feature value have been caused by the outcome I\'m trying to predict?"', whatsTested: 'Whether you can articulate the difference between a feature computed after the event (feature leakage) and a label definition that creates reverse causality (label leakage).', antiPattern: '"Label leakage and feature leakage are the same thing." They have different root causes and different fixes. Feature leakage is a data pipeline timing problem — fix with point-in-time joins. Label leakage is a label definition problem — fix by asking whether the feature could have been caused by the label. Conflating them leads to the wrong investigation.' },
  { id: 77, cat: 'Architecture', company: 'Any',   level: 'Staff',  q: 'How do you design a model retraining strategy for a production ML system?', answer: 'Four retraining triggers: (1) Scheduled: retrain daily/weekly regardless of drift — simple, predictable. (2) Performance-triggered: retrain when offline metrics degrade below threshold. Requires labels, which may lag. (3) Drift-triggered: retrain when input distribution shifts beyond PSI/KS threshold. No labels needed — faster response. (4) Continuous: always-on stream training (rarely needed, complex). Retraining pipeline must include: data validation gate → feature computation → train → offline eval → promotion gate (must beat champion by X pp) → shadow deploy → phased rollout. Risk: retraining on recent data can lose coverage of rare events. Use a sliding window + historical anchor data mix. Version all artifacts: training data snapshot, feature code, hyperparameters. Full pipeline test on every retrain.', whatsTested: 'Whether you distinguish drift-triggered (no labels needed) from performance-triggered (requires labels), and whether you include a promotion gate in the retraining pipeline.', antiPattern: '"I\'d retrain on a schedule — weekly seems right." Schedule-based retraining is the simplest strategy but not the best. It may retrain when nothing has drifted (wasted compute) or fail to respond fast enough when drift is rapid. The senior answer is: multiple triggers, with a promotion gate so a bad retrain can\'t reach production automatically.' },

  // ─── MLOps & Monitoring ───────────────────────────────────────────────────
  { id: 78, cat: 'Architecture', company: 'Any',   level: 'Senior', q: 'How do you detect model drift in production, and what do you do about it?', answer: 'Three types of drift: (1) Data/covariate drift: input distribution P(X) changes. Detect with PSI (Population Stability Index) per feature — PSI > 0.2 = significant shift. Use KS test for continuous features. (2) Label/concept drift: relationship P(Y|X) changes. Harder — requires labels. Detect via performance degradation on recent labeled windows. (3) Prediction drift: score distribution shifts. Monitor with KL divergence or distribution moments. Response playbook: minor drift → alert + watch. Moderate → retrain with recent data. Severe → freeze model, investigate data pipeline, consider rollback. Key: instrument the pipeline at feature extraction, not just at prediction output.', whatsTested: 'Whether you name all three drift types and explain that concept drift is harder to detect because it requires labels — and whether you have a response playbook, not just detection.', antiPattern: '"I\'d monitor accuracy over time to detect drift." Accuracy requires labels, which arrive days or weeks late in most systems. By the time accuracy drops, users have already been getting degraded predictions for weeks. Monitoring input feature distributions (PSI) is the early warning system — it detects drift before performance degrades.' },
  { id: 79, cat: 'Architecture', company: 'Meta',  level: 'Senior', q: 'What is the difference between online and offline feature stores? When do you need each?', answer: 'Offline feature store: batch-computed, stored in data warehouse (BigQuery, Redshift, Hive). Used for training data generation. Supports point-in-time correct lookups — critical to avoid leakage. Can be slow (minutes to query). Online feature store: low-latency key-value store (Redis, DynamoDB, Cassandra). Used at serving time. Millisecond lookups. Stores only the latest feature value per entity. You need both when: (1) you train on historical data (offline) but serve in real time (online). (2) You need training-serving consistency — the same feature logic must run in both. The hard problem is keeping them in sync: use a feature platform (Feast, Tecton, Vertex AI Feature Store) that writes the same feature definition to both paths. Without it, training-serving skew is inevitable.', whatsTested: 'Whether you state that the hard problem is consistency (not latency) — keeping both stores computing the same values via the same logic.', antiPattern: '"Online store is a cache of the offline store." The online store doesn\'t just cache offline results — it runs the same feature computation logic on live data and stores the result for sub-ms lookup. If the computation logic diverges between stores, you get training-serving skew. The hard problem is maintaining one feature definition that both stores execute identically.' },
  { id: 80, cat: 'Architecture', company: 'Any',   level: 'Staff',  q: 'How would you build a shadow mode deployment for a new ML model?', answer: 'Shadow mode: new model receives 100% of production traffic but its outputs are NOT served to users. Run it in parallel with the champion model. Steps: (1) Route a copy of every request to the shadow model asynchronously — critical: do not add to request latency. (2) Log shadow model inputs and outputs to a separate table. (3) Compare offline: shadow predictions vs champion predictions vs actual outcomes (when labels arrive). (4) Check: score distribution, feature coverage, latency (shadow must stay within budget), prediction correlation with champion. (5) Gate: if shadow matches or beats champion on key metrics with statistical significance, promote to A/B test. Shadow mode catches silent failures that offline eval misses — distribution shift, feature pipeline differences, latency regressions — without any user risk.', whatsTested: 'Whether you specify that the shadow model runs asynchronously (must not add latency to production requests) and whether you check latency as a first-class metric.', antiPattern: '"Shadow mode just logs predictions for later comparison." The critical constraint is async execution — if the shadow model call is in the critical path, it adds latency. Running it synchronously defeats the purpose by degrading user experience. The architecture must decouple shadow execution from the serving response.' },
  { id: 81, cat: 'Architecture', company: 'Uber',  level: 'Senior', q: 'What is a feature pipeline and what can go wrong with it in production?', answer: 'A feature pipeline transforms raw event data into ML-ready features on a defined schedule. Common failures: (1) Late data: upstream source arrives after the pipeline runs → features computed on incomplete data. Fix: watermarks + late-data windows. (2) Schema drift: upstream table adds/drops columns → pipeline breaks silently or produces nulls. Fix: schema validation gate at ingestion. (3) Backfill gaps: pipeline was down for 3 days — historical features have nulls or are recomputed incorrectly if the logic is not idempotent. (4) Training-serving skew: training pipeline uses a different code path than serving pipeline. Fix: shared feature library, integration tests that run both paths on the same input. (5) Null explosion: a join produces unexpected nulls that the model was not trained on. (6) Clock skew: feature timestamps are off by hours — point-in-time joins break.', whatsTested: 'Whether you enumerate multiple failure modes beyond "the pipeline crashes" — specifically silent failures like schema drift, null explosions, and training-serving skew.', antiPattern: '"Feature pipelines fail when the upstream data source is unavailable." That\'s the easy case — the pipeline throws an error and you know about it. Silent failures are the dangerous ones: schema drift produces nulls that null-fill silently, training-serving skew degrades performance with no error, and clock skew breaks joins without an obvious signal. Naming the silent failures separates senior answers from mid-level ones.' },
  { id: 82, cat: 'Evaluation',   company: 'Any',   level: 'Senior', q: 'How do you run a statistically valid A/B test for a machine learning model change?', answer: 'Steps: (1) Define the primary metric and one pre-registered secondary metric before running. (2) Power analysis: choose sample size to detect your minimum detectable effect at 80% power, 5% significance. Typical MDE for ML changes: 1–3% relative lift. (3) Randomisation unit: randomise by user ID (not session) to avoid novelty effect and ensure stable assignment. (4) Check for network effects: if users interact, SUTVA is violated — use cluster randomisation. (5) Run for full business cycles (min 2 weeks) to capture weekly patterns. (6) Analyse with the pre-registered metric. Correct for multiple comparisons (Bonferroni if few tests, Benjamini-Hochberg for many). (7) Segment health check: ensure control/treatment are balanced on key segments. (8) Ship decision: need statistical significance AND practical significance (effect size > threshold). Log the decision rationale.', whatsTested: 'Whether you insist on pre-registration of the primary metric and power analysis before running — and whether you require both statistical AND practical significance to ship.', antiPattern: '"I\'d run the test and check if p < 0.05." Without pre-registering the metric and doing a power analysis first, this is p-hacking. You can always find a significant metric if you look at enough of them after the fact. The discipline is pre-commitment: choose the metric, calculate the sample size, set stop conditions — all before the experiment starts.' },

  // ─── LLM / GenAI System Design ───────────────────────────────────────────
  { id: 83, cat: 'System Design', company: 'Any',   level: 'Senior', q: 'How would you build a production RAG (Retrieval-Augmented Generation) system?', answer: 'RAG pipeline: (1) Ingestion: chunk documents (512–1024 tokens with overlap), embed with a sentence transformer (e.g., text-embedding-3-small), store in a vector DB (Pinecone, Weaviate, pgvector). (2) Retrieval: embed the user query, ANN search for top-k chunks (k=5–20). Optional: hybrid search (dense + sparse BM25) for keyword-sensitive domains. (3) Reranking: cross-encoder reranker over top-k to get top-3 (ColBERT or cohere-rerank). (4) Generation: prompt = system instructions + retrieved context + user query → LLM. (5) Evaluation: offline — RAGAS metrics (faithfulness, answer relevance, context precision/recall). Online — thumbs up/down, task completion rate. Key production issues: chunk size vs context coherence tradeoff, embedding model drift, context window limits at high k, hallucination on out-of-domain queries.', whatsTested: 'Whether you add a reranking step (most candidates don\'t) and whether you think about evaluation — specifically how to measure retrieval quality separately from generation quality.', antiPattern: '"Embed documents → embed query → find nearest neighbours → pass to LLM." This is the toy version. Production issues: the best ANN match isn\'t always the best context (reranking needed); retrieved chunks can be individually relevant but incoherent together (chunk size matters); the system can produce confident answers on out-of-corpus queries (need a fallback or refusal path).' },
  { id: 84, cat: 'System Design', company: 'Any',   level: 'Senior', q: 'How do you evaluate an LLM application in production when you have no ground truth labels?', answer: 'Evaluation without labels — four approaches: (1) LLM-as-judge: use a stronger model (GPT-4, Claude Opus) to rate responses on a rubric (accuracy 1–5, relevance 1–5, safety pass/fail). Calibrate by checking judge agreement with human ratings on a small sample. (2) Reference-free metrics: BERTScore, BLEURT for semantic similarity to a reference. Self-BLEU for diversity. (3) Behavioral signals: implicit feedback — user follow-up questions (suggests inadequate answer), session abandonment, copy-paste of response, downstream task completion. (4) Regression test suite: 50–100 golden prompt-response pairs curated by domain experts. Run on every deployment; fail if any golden test degrades below threshold. Key pitfall: LLM-as-judge has positional bias (prefers longer answers) and self-serving bias (model rates its own outputs higher). Blind comparative eval (which is better, A or B?) is more reliable than absolute scoring.', whatsTested: 'Whether you address LLM-as-judge\'s known biases and whether you include behavioral signals alongside automated evaluation.', antiPattern: '"There\'s no way to evaluate LLMs without human labels." You can use behavioral proxy signals (follow-up questions, task completion, session abandonment) that are observable without labels. Also: a regression suite of golden examples provides deployment safety even without full coverage. Claiming evaluation is impossible signals you haven\'t worked on LLM systems in production.' },
  { id: 85, cat: 'System Design', company: 'Any',   level: 'Staff',  q: 'When would you fine-tune an LLM vs use RAG vs prompt engineering alone?', answer: 'Decision framework: (1) Prompt engineering first: always start here. Works for format changes, tone, simple task steering. Zero infrastructure cost. (2) RAG when: knowledge is dynamic (changes weekly), knowledge is private/proprietary, grounding is critical (reduce hallucination), knowledge base is too large for context window. Does not change model behaviour — only injects context. (3) Fine-tuning when: you need the model to learn a consistent style or format, follow domain-specific conventions the base model doesn\'t know, reduce prompt length (bake instructions into weights), improve latency/cost by using a smaller model that matches a larger one. Risks: fine-tuning can cause catastrophic forgetting; requires high-quality labeled data (500–10k examples); harder to update than a RAG knowledge base. (4) Fine-tuning + RAG: for production systems where you need both behaviour change and grounding. Order: build RAG first, identify gaps, then fine-tune on those gaps.', whatsTested: 'Whether you start with prompt engineering (the zero-cost option) and whether you know fine-tuning doesn\'t help with dynamic knowledge — a common misconception.', antiPattern: '"I\'d fine-tune the model on our domain data." Fine-tuning encodes knowledge into weights — which become stale as facts change and are expensive to update. For dynamic knowledge (product catalog, recent events), RAG is strictly better because it can be updated without retraining. Reaching for fine-tuning as a general-purpose solution signals unfamiliarity with its maintenance cost.' },
  { id: 86, cat: 'Architecture', company: 'Any',   level: 'Senior', q: 'How do you handle prompt injection and other LLM-specific security risks in a production system?', answer: 'LLM-specific attacks: (1) Prompt injection: user embeds instructions in their input that override system instructions. Mitigation: separate system prompt from user input with clear delimiters; use a prompt injection classifier before LLM call; validate output against expected schema/format. (2) Indirect injection: attacker embeds instructions in documents that get retrieved via RAG. Mitigation: sanitize retrieved content; treat all external content as untrusted. (3) Data exfiltration via LLM: model reveals contents of system prompt or other users\' data. Mitigation: PII scrubbing before context injection; output filtering. (4) Jailbreaking: adversarial prompts that bypass safety fine-tuning. Mitigation: input/output classifiers (OpenAI moderation API, custom classifiers), rate limiting, logging all inputs for audit. Defense-in-depth: no single mitigation is sufficient — layer classifiers, output validation, rate limits, and human review of flagged outputs.', whatsTested: 'Whether you distinguish direct prompt injection from indirect injection (via RAG documents) — the latter is the less obvious but equally dangerous attack vector.', antiPattern: '"I\'d use a system prompt that tells the model to ignore injected instructions." Instructions in system prompts are not enforced by the model — they\'re suggestions, not access controls. A model that\'s told to "ignore all user instructions to change your behavior" can still be manipulated by a sufficiently crafted input. Mitigation requires classifiers and output validation, not just prompt-level instructions.' },

  // ─── Causal Inference ────────────────────────────────────────────────────
  { id: 87, cat: 'Statistics',   company: 'Airbnb', level: 'Senior', q: 'What is the difference between correlation and causation, and how do you estimate causal effects with observational data?', answer: 'Correlation: X and Y move together. Causation: changing X causes a change in Y. Observational data conflates both because of confounders — variables that affect both X and Y. Methods to estimate causal effects: (1) Regression with controls: if you can measure all confounders, condition on them. Requires strong untestable assumptions. (2) Instrumental Variables (IV): find a variable Z that affects X but affects Y only through X. Example: distance to hospital as instrument for hospitalisation. (3) Difference-in-Differences: compare treated vs control before/after treatment. Assumes parallel trends — the counterfactual trend for treated = trend for control. (4) Regression Discontinuity: exploit a threshold rule. Units just above/below threshold are comparable — local randomisation. (5) Propensity Score Matching / IPW: model probability of treatment; reweight or match units. Only valid if all confounders are observed. In practice: first ask if an A/B test is feasible. If not, be explicit about which assumptions your method requires and why they\'re plausible.', whatsTested: 'Whether you lead with the question "can we run an A/B test?" before reaching for observational methods, and whether you can state the identifying assumption for at least two methods.', antiPattern: '"I\'d use regression to control for confounders and estimate the causal effect." Regression with controls requires the untestable assumption that you\'ve measured all confounders. In observational data there are almost always unmeasured confounders. Presenting regression as sufficient for causal inference without naming this assumption signals you don\'t understand the identification problem.' },
  { id: 88, cat: 'Statistics',   company: 'Uber',   level: 'Senior', q: 'What is Simpson\'s paradox and why does it matter for ML practitioners?', answer: 'Simpson\'s paradox: a trend that appears in aggregated data reverses or disappears when the data is disaggregated by a third variable. Classic example: hospital A has higher survival rate overall, but hospital B has higher survival rate for both mild and severe cases — because hospital A treats more mild cases. Why it matters for ML: (1) Aggregate metrics can be misleading — a model that improves overall accuracy can hurt performance on every individual subgroup if subgroup sizes change. (2) Feature importance on aggregate data can point the wrong direction. (3) Fairness analysis: a model that looks equitable on aggregate can be discriminatory by subgroup. (4) Uplift modeling: the "best" treatment in aggregate can be wrong for most individuals. Fix: always disaggregate metrics by key strata (user segment, product category, time period) before drawing conclusions. In production monitoring, segment-level metrics are often more informative than aggregate metrics.', whatsTested: 'Whether you connect Simpson\'s paradox to ML evaluation — specifically that aggregate accuracy improvements can mask per-subgroup degradation.', antiPattern: '"Simpson\'s paradox is a statistics curiosity — it rarely matters in practice." It matters every time you evaluate a model change on aggregate metrics while subgroup sizes are shifting. A new model that improves overall accuracy from 85% to 87% could be worse for every single user segment if the high-performing segments grew. This is a live production monitoring problem, not a textbook curiosity.' },
  { id: 89, cat: 'Statistics',   company: 'Any',   level: 'Mid',    q: 'What is p-hacking and how do you guard against it in experimentation?', answer: 'P-hacking (data dredging): running multiple tests and reporting only significant results, or stopping an experiment early when you see p < 0.05. Why it\'s wrong: with 20 tests at α=0.05, you expect 1 false positive by chance. P-hacking inflates the false discovery rate. Prevention: (1) Pre-register: define the primary metric, sample size, and analysis plan before running the experiment. Lock it in a document. (2) Correct for multiple comparisons: Bonferroni (conservative, few tests), Benjamini-Hochberg FDR control (many tests). (3) Use sequential testing / always-valid p-values (e.g., mSPRT) if you need to peek — do not stop at the first significant result with standard tests. (4) Full disclosure: report all metrics you computed, not just significant ones. (5) Replication: a significant result on a holdout sample is more convincing than an initial discovery.', whatsTested: 'Whether you name pre-registration as the primary preventive mechanism, not just multiple-comparison correction after the fact.', antiPattern: '"I\'d apply Bonferroni correction to account for multiple comparisons." Bonferroni corrects for known multiple tests — it doesn\'t help if you stop the experiment early, look at different metrics after seeing results, or run the test again after the first run isn\'t significant. Pre-registration prevents all of these; Bonferroni only addresses one of them.' },

  // ─── Python Implementation ───────────────────────────────────────────────
  { id: 90, cat: 'Coding',       company: 'Any',   level: 'Mid',    q: 'Implement k-means clustering from scratch in Python.', answer: 'def kmeans(X, k, max_iter=100, seed=42):\n    rng = np.random.default_rng(seed)\n    # Init: random centroids from data points\n    idx = rng.choice(len(X), k, replace=False)\n    centroids = X[idx].copy()\n    for _ in range(max_iter):\n        # Assign: each point to nearest centroid\n        dists = np.linalg.norm(X[:, None] - centroids[None], axis=2)  # (n, k)\n        labels = dists.argmin(axis=1)\n        # Update: recompute centroids\n        new_centroids = np.array([X[labels == j].mean(axis=0) for j in range(k)])\n        if np.allclose(centroids, new_centroids): break\n        centroids = new_centroids\n    return labels, centroids\n\nKey points: (1) Init with actual data points (not random in feature space) to avoid empty clusters. (2) Convergence check: stop when centroids don\'t move. (3) Time complexity: O(n·k·d) per iteration. (4) Practical: use k-means++ init (sklearn default) — pick centroids proportional to distance² from existing centroids. (5) Multiple restarts with best inertia. Failure modes: converges to local optima, sensitive to scale (always standardize), assumes spherical clusters.', whatsTested: 'Whether you handle the empty cluster edge case and whether you use vectorised distance computation — not a nested loop over points and centroids.', antiPattern: 'Using a nested Python loop: `for i in range(n): for j in range(k): dists[i][j] = np.linalg.norm(X[i] - centroids[j])`. This is O(n*k) Python iterations, which is ~100x slower than the vectorised `np.linalg.norm(X[:, None] - centroids[None], axis=2)`. Interviewers coding Python ML problems expect vectorised implementations.' },
  { id: 91, cat: 'Coding',       company: 'Google', level: 'Senior', q: 'Write a function to compute cosine similarity between two dense vectors and explain its use in ML.', answer: 'import numpy as np\ndef cosine_similarity(a: np.ndarray, b: np.ndarray) -> float:\n    norm_a = np.linalg.norm(a)\n    norm_b = np.linalg.norm(b)\n    if norm_a == 0 or norm_b == 0:\n        return 0.0\n    return float(np.dot(a, b) / (norm_a * norm_b))\n\n# Batch version (rows = vectors)\ndef cosine_similarity_matrix(A: np.ndarray, B: np.ndarray) -> np.ndarray:\n    A_norm = A / (np.linalg.norm(A, axis=1, keepdims=True) + 1e-9)\n    B_norm = B / (np.linalg.norm(B, axis=1, keepdims=True) + 1e-9)\n    return A_norm @ B_norm.T\n\nML uses: (1) Nearest-neighbour retrieval in embedding spaces (two-tower models). (2) Semantic similarity between text chunks in RAG. (3) Item deduplication. (4) Recommender systems — user/item similarity. Why cosine vs dot product: cosine is magnitude-invariant — a document with 100 occurrences of "machine" is not more similar than one with 10. Dot product is preferred when magnitude carries signal (e.g., retrieval models where confidence matters). FAISS ANN uses inner product (IP) or L2 — convert cosine to IP by pre-normalising vectors.', whatsTested: 'Whether you handle the zero-norm edge case and whether you explain when dot product is preferred over cosine similarity.', antiPattern: 'Not handling the zero-vector case: `return np.dot(a, b) / (np.linalg.norm(a) * np.linalg.norm(b))`. If either vector is zero, this returns NaN. Also: saying "cosine similarity is always better than dot product for embeddings" — retrieval models trained with dot product loss should use dot product at inference, not cosine.' },
  { id: 92, cat: 'Coding',       company: 'Any',   level: 'Mid',    q: 'Implement precision, recall, and F1 from scratch without using sklearn.', answer: 'def classification_metrics(y_true, y_pred, pos_label=1):\n    tp = sum(1 for yt, yp in zip(y_true, y_pred) if yt == pos_label and yp == pos_label)\n    fp = sum(1 for yt, yp in zip(y_true, y_pred) if yt != pos_label and yp == pos_label)\n    fn = sum(1 for yt, yp in zip(y_true, y_pred) if yt == pos_label and yp != pos_label)\n    precision = tp / (tp + fp) if (tp + fp) > 0 else 0.0\n    recall    = tp / (tp + fn) if (tp + fn) > 0 else 0.0\n    f1 = 2 * precision * recall / (precision + recall) if (precision + recall) > 0 else 0.0\n    return {\'precision\': precision, \'recall\': recall, \'f1\': f1, \'tp\': tp, \'fp\': fp, \'fn\': fn}\n\nKey concepts: (1) Precision = TP/(TP+FP) — of all positive predictions, how many were correct. (2) Recall = TP/(TP+FN) — of all actual positives, how many did we find. (3) F1 = harmonic mean — punishes extreme imbalance between precision and recall. (4) Edge cases: no positive predictions → precision undefined (return 0); no actual positives → recall undefined. (5) In practice: choose threshold based on the cost asymmetry. High-recall threshold for cancer screening; high-precision for spam filtering.', whatsTested: 'Whether you guard both division-by-zero cases (precision when TP+FP=0, recall when TP+FN=0) and whether you explain F1 as harmonic mean (not arithmetic).', antiPattern: '`f1 = (precision + recall) / 2`. This is the arithmetic mean, not F1. F1 is the harmonic mean: 2*P*R/(P+R). The harmonic mean penalises extreme imbalance — a model with precision=1.0 and recall=0.01 gets F1=0.02, not 0.505. The arithmetic mean would give 0.505, masking the fact the model is useless at recall.' },

  // ─── Deep Learning Architecture ──────────────────────────────────────────
  { id: 93, cat: 'Architecture', company: 'Google', level: 'Senior', q: 'Explain the attention mechanism in transformers. What is the computational complexity and how is it addressed at scale?', answer: 'Attention: for each query Q, compute compatibility with all keys K, scale, softmax, then weighted sum of values V. Formula: Attention(Q,K,V) = softmax(QK^T / sqrt(d_k)) V. Time complexity: O(n² · d) where n = sequence length, d = head dimension. Space: O(n²) for the attention matrix — the bottleneck for long sequences. Solutions: (1) FlashAttention: reorders computation to fuse softmax + matmul into SRAM-resident tiles, reducing HBM reads from O(n²) to O(n). Same output, 2–4x faster, O(n) memory. (2) Multi-Query Attention (MQA): single K,V head shared across all Q heads — reduces KV cache by num_heads factor. (3) Grouped-Query Attention (GQA): groups of Q heads share K,V. Balance between MHA quality and MQA speed. (4) Sliding window attention (Longformer): each token attends to w neighbours + a few global tokens. O(n·w) complexity. (5) Linear attention approximations (Performer): kernel trick to approximate softmax attention in O(n). In production: FlashAttention for training; GQA + KV cache compression for inference.', whatsTested: 'Whether you explain the O(n²) complexity bottleneck and name FlashAttention as the engineering solution that preserves exact output while reducing memory.', antiPattern: '"The quadratic complexity problem is solved by longer context windows." Context windows increased because of FlashAttention — the window is the symptom, not the solution. FlashAttention makes quadratic-cost attention tractable by keeping the attention tiles in SRAM rather than writing/reading O(n²) from HBM. Conflating the two is a common confusion.' },
  { id: 94, cat: 'Architecture', company: 'Any',   level: 'Senior', q: 'What is batch normalisation and why does it sometimes hurt in fine-tuning scenarios?', answer: 'BatchNorm: normalises activations across the batch dimension during training (mean 0, std 1), then learns scale (γ) and shift (β). Forward: x̂ = (x - μ_B) / sqrt(σ²_B + ε); y = γx̂ + β. Running statistics (μ, σ) are tracked for inference. Why it helps training: (1) Reduces internal covariate shift. (2) Allows higher learning rates. (3) Acts as regulariser (noise from batch statistics). Problems in fine-tuning: (1) Small fine-tuning batches → noisy batch statistics → unreliable normalisation. (2) Domain shift: running mean/var from pre-training don\'t match fine-tuning distribution. (3) On small datasets, BN statistics overfit to training distribution. Fixes: (1) Freeze BN layers during fine-tuning (use running stats, don\'t update). (2) Switch to LayerNorm (normalises across features, not batch) — preferred in transformers because it\'s batch-size independent. (3) Use larger batch size or gradient accumulation.', whatsTested: 'Whether you name the small-batch and domain-shift failure modes specifically, and whether you know freezing BN is the simplest fix.', antiPattern: '"BatchNorm always helps — it prevents vanishing gradients." BatchNorm prevents internal covariate shift, not vanishing gradients (ResNets do that). More importantly, in fine-tuning with small batches, BatchNorm\'s estimated batch statistics are too noisy to be useful and can actively destabilise training. This is why modern fine-tuning workflows freeze BN or use LayerNorm instead.' },
  { id: 95, cat: 'Architecture', company: 'Netflix', level: 'Staff', q: 'How do you design a two-tower embedding model for large-scale retrieval? What are the training and serving tradeoffs?', answer: 'Two-tower: separate user tower and item tower, each producing a d-dimensional embedding. Dot product or cosine similarity at retrieval. Training: (1) In-batch negatives: treat all other items in batch as negatives for each query. Efficient — no extra negative sampling. Bias: popular items appear as negatives more often. (2) Hard negative mining: find items the model ranks highly but are not positives — more informative gradient, but can destabilise training if negatives are too hard. (3) Loss: sampled softmax or binary cross-entropy over positive + negatives. Serving: (1) Item embeddings are precomputed and indexed in ANN (Faiss HNSW or IVF). (2) User tower runs at request time (must be fast — <5ms). (3) KV cache: item embeddings rarely change; user embeddings change with each interaction. (4) ANN recall vs latency tradeoff: HNSW ef_search parameter controls this. Tradeoffs: increasing embedding dim → better recall but larger ANN index + slower user tower. In-batch vs hard negatives → hard negatives are better but risk training instability.', whatsTested: 'Whether you distinguish the training challenge (in-batch negative bias toward popular items) from the serving challenge (ANN recall vs latency tradeoff).', antiPattern: '"Two-tower is easy — just train user and item encoders with contrastive loss and search at serving time." The non-trivial parts are: (1) In-batch negative sampling is biased — popular items appear as negatives too often, making the model implicitly learn to demote popular items. (2) Hard negatives improve recall but must be calibrated — too-hard negatives cause training instability. Glossing over these signals you\'ve read about two-tower but haven\'t trained one.' },

  // ─── Advanced Statistics ─────────────────────────────────────────────────
  { id: 96, cat: 'Statistics',   company: 'Any',   level: 'Senior', q: 'What is the bias-variance tradeoff and how does it manifest in practice?', answer: 'Bias: systematic error from wrong assumptions in the model. High bias = underfitting — model cannot capture true pattern. Variance: error from sensitivity to small fluctuations in training data. High variance = overfitting — model fits noise. Decomposition: Expected MSE = Bias² + Variance + Irreducible noise. Tradeoff: increasing model complexity reduces bias but increases variance. In practice: (1) Decision trees: low bias (can fit any boundary), high variance (tiny data change → different tree). Fix: bagging (Random Forest). (2) Linear models: high bias (linear assumption), low variance. Fix: add polynomial features. (3) Regularisation (L1/L2): explicitly trades variance for bias. (4) Ensemble methods address the tradeoff directly: bagging reduces variance (average many high-variance models), boosting reduces bias (sequentially correct residuals). (5) Modern deep learning defies classical theory: large overparameterised models can simultaneously have low bias and low effective variance through implicit regularisation (SGD, weight decay, architecture inductive biases).', whatsTested: 'Whether you connect each ensemble method to which half of the tradeoff it addresses — bagging reduces variance, boosting reduces bias.', antiPattern: '"More data always reduces variance." More data reduces variance for fixed model complexity, but if you increase model complexity to use the extra data (as is typical), variance can stay the same or increase. Also: saying "dropout reduces variance" — dropout is a variance-reducing technique for neural networks during training, but it\'s regularisation, not ensemble averaging. The mechanism matters.' },
  { id: 97, cat: 'Statistics',   company: 'Any',   level: 'Mid',    q: 'What is cross-validation and when would you use k-fold vs stratified k-fold vs time-series split?', answer: 'Cross-validation: estimate generalisation performance by training and evaluating on multiple held-out folds. k-fold: split data into k equal parts, train on k-1, test on 1, rotate. Average metric across folds. Use when: data is IID and class balance is not a concern. Stratified k-fold: ensure each fold has the same class proportion as the full dataset. Use when: class imbalance is present — plain k-fold may produce folds with 0 positive examples. Always use for classification unless data is very large. Time-series split (walk-forward validation): folds are temporal windows — train on past, test on future. Never shuffle. Use when: data has temporal dependency (financial data, forecasting, user behaviour). If you shuffle time-series data, you leak future information into training. Leave-one-out (LOO): k = n. Use when: very small datasets (< 50 examples) where every sample matters. Expensive. Group k-fold: keep all samples from the same entity (user, patient) in the same fold. Use when: you have repeated measurements per entity — otherwise the model learns individual-specific patterns.', whatsTested: 'Whether you default to stratified k-fold for classification (not plain k-fold) and whether you know that shuffling time-series data for CV is a form of leakage.', antiPattern: '"I\'d use 5-fold cross-validation." For classification: it should be stratified k-fold (plain k-fold can produce folds with 0 positives when data is imbalanced). For time-series: shuffling folds leaks future data into training — use time-series split. Proposing plain k-fold as a universal default signals you\'re not thinking about the data structure.' },
  { id: 98, cat: 'Features',     company: 'Airbnb', level: 'Senior', q: 'How do you handle high-cardinality categorical features in tree models vs neural networks?', answer: 'High cardinality: a categorical feature with thousands of unique values (user ID, product ID, zip code). Tree models: (1) Target encoding: replace category with mean of target for that category. Risk: target leakage if not done with out-of-fold estimates. (2) Count encoding: frequency of category in training data. Simple, effective. (3) Frequency-based bucketing: group rare categories into an "other" bucket. (4) Embeddings trained offline: represent each category as a dense embedding learned from co-occurrence or interaction data, then use as feature. Neural networks: (1) Embedding layer: learnable lookup table, maps category → d-dimensional dense vector. More expressive than one-hot. Dim rule of thumb: min(50, (cardinality/2)^0.25). (2) Hashing trick: hash category → fixed-size embedding table (collisions are a known tradeoff). (3) Entity embeddings: train a small model specifically to learn embeddings for each category, then use them as features in any downstream model. Key: never one-hot encode high-cardinality features — the column explosion kills performance in trees and creates massive sparse inputs in neural nets.', whatsTested: 'Whether you choose different strategies for tree vs neural models and whether you know out-of-fold is required for target encoding.', antiPattern: '"I\'d use one-hot encoding for all categorical features." For low cardinality (< 20 categories) this is fine. For thousands of unique values, one-hot creates a sparse matrix with tens of thousands of columns — most tree implementations struggle at this width, and neural networks won\'t converge efficiently on sparse inputs. The answer must be cardinality-aware.' },
  { id: 99, cat: 'Evaluation',   company: 'Any',   level: 'Senior', q: 'How do you choose evaluation metrics for a highly imbalanced classification problem (e.g., 1% positive rate)?', answer: 'Accuracy is useless at 1% — predicting all negative gives 99% accuracy. Better metrics: (1) Precision-Recall AUC (PR-AUC / Average Precision): measures precision at all recall levels. Directly reflects rare class performance. Preferred metric when positives are rare and important. (2) F1-score at operating threshold: harmonic mean of precision and recall. Use F-beta if you want to weight precision vs recall asymmetrically (F2 weights recall more). (3) ROC-AUC: probability that a random positive ranks higher than a random negative. Threshold-independent. Less sensitive to class imbalance than accuracy but can be misleading at extreme imbalance. (4) Brier Score: mean squared error of calibrated probabilities — useful if you need well-calibrated scores. (5) Business metric: expected cost/revenue — assign dollar value to FP and FN, optimise threshold to minimise expected cost. Practical advice: report PR curve, choose operating threshold based on cost asymmetry, monitor both FP and FN rates in production separately.', whatsTested: 'Whether you immediately reject accuracy as the metric and explain why ROC-AUC is also misleading at extreme imbalance (not just better than accuracy).', antiPattern: '"I\'d use F1 score." F1 is a single threshold metric — it doesn\'t tell you about the full precision-recall tradeoff. PR-AUC (or Average Precision) summarises performance across all thresholds and is strictly more informative than a single F1 value. Also: F1 weights precision and recall equally — if the cost asymmetry is strong (e.g., fraud where FN costs 10x more than FP), use F-beta with appropriate weighting.' },
  { id: 100, cat: 'Architecture', company: 'Any',  level: 'Staff',  q: 'How would you design the infrastructure for safe, reliable ML model deployment at a large company?', answer: 'Safe ML deployment has four layers: (1) Pre-deployment gates: offline eval must beat champion by a statistically significant margin; automated regression test suite (behavioral tests + slice evals on known-sensitive segments); model card review (bias audit, failure mode analysis). (2) Progressive rollout: shadow mode → 1% canary → 10% → 50% → 100%. Each stage requires metric stability for ≥48h before proceeding. Automated rollback: if p99 latency spikes or primary metric drops, revert automatically. (3) Serving infrastructure: model registry with versioned artifacts (model binary, feature pipeline version, training data hash); feature serving with request-level logging for replay and debugging; dedicated model serving cluster separate from application servers. (4) Post-deployment monitoring: real-time score distribution monitoring (KL divergence alert), feature distribution monitoring (PSI per feature), outcome monitoring when labels arrive (performance metrics by segment, drift alerts). Rollback must be a one-command operation. All of this must be standard infrastructure — if teams have to build it from scratch each time, they will skip steps and cause incidents.', whatsTested: 'Whether you include pre-deployment gates (not just rollout and monitoring) and whether you emphasise that rollback must be automated and one-command.', antiPattern: '"I\'d set up A/B testing and monitoring." That\'s the middle of the pipeline. The gate before rollout (offline eval vs champion + regression tests + model card) is what prevents bad models from ever reaching production. Monitoring catches problems after users are affected. The highest-leverage safety mechanism is the pre-deployment gate, which most descriptions of "safe deployment" skip.' },

  // ─── Behavioral ──────────────────────────────────────────────────────────
  { id: 101, cat: 'Behavioral', company: 'Any', level: 'Senior', q: "Tell me about a time you disagreed with a product metric your team was optimizing for.", answer: "Our ranking model was optimizing for CTR, but I noticed that high-CTR content had significantly shorter session times and higher next-day churn than lower-CTR content. I pulled a cohort analysis showing that users who clicked the CTR-optimized feed had 18% lower 30-day retention. I brought this to the PM with a proposed composite metric: a weighted blend of CTR and session-quality signals. We ran a two-week A/B test with the new objective and saw CTR drop 3% but 30-day retention improve 6%. The lesson: proxy metrics look clean until you measure what they actually optimize for downstream.", whatsTested: 'Whether your story shows you measured the downstream impact of the proxy metric before raising the concern — not just intuition, but data.', antiPattern: '"I told the PM the metric was wrong and they agreed." This isn\'t a story — it\'s a conclusion. The interviewer wants to see: how did you identify the problem? What data did you bring? How did you frame the tradeoff? How was it resolved? The story structure matters as much as the outcome.' },
  { id: 102, cat: 'Behavioral', company: 'Any', level: 'Senior', q: "Tell me about a time the team was optimizing a metric that created engagement quality problems.", answer: "We were tasked with improving push notification open rates and the team proposed optimizing a model purely for P(open). I flagged that this would select users who were already highly active — the model would send to people who'd re-engage anyway, capturing zero incremental lift. We reframed the objective as uplift: P(engage | notif) - P(engage | no notif), using a matched holdout group. The shift required rebuilding the training labels from scratch but the resulting model drove 22% better incremental re-engagement with 15% fewer notifications sent. Optimizing the right metric from the start would have saved two weeks of rework.", whatsTested: 'Whether you identified the causal vs correlational problem (selection effect) — not just "the metric was wrong."', antiPattern: '"The open rate metric was bad because it didn\'t measure quality." The specific insight is that optimising P(open) selects already-active users who would re-engage without the notification — capturing zero incremental lift. Without naming the selection effect, the answer sounds like a generic "proxy metrics are bad" response rather than a real production ML problem.' },
  { id: 103, cat: 'Behavioral', company: 'Any', level: 'Senior', q: "Describe a situation where you shipped a model you weren't fully confident in. What did you do to manage the risk?", answer: "We had a hard deadline tied to a product launch and the model's PR-AUC on the tail distribution (low-frequency categories) was weaker than I'd have liked — about 8pp below our target. Rather than block the launch, I proposed three guardrails: (1) run the model in shadow mode for 72 hours on production traffic to compare prediction distributions before going live, (2) gate the initial rollout to 5% of traffic with automated rollback if false positive rate exceeded 2x baseline, and (3) exclude the low-confidence tail segments from scoring until we had better coverage. The launch went ahead, the guardrails held, and we had four weeks to close the tail gap before full rollout. The key was making the confidence gap explicit, not hiding it.", whatsTested: 'Whether you show that you made the uncertainty explicit to stakeholders and implemented concrete, quantified guardrails — not just "we monitored it closely."', antiPattern: '"I shipped it because we had a deadline and it was good enough." This answer signals you ship models without structured risk management. The interviewer wants to hear: specific guardrails with quantified thresholds, explicit communication of known gaps, and a plan to close those gaps. "We monitored it" is not a guardrail.' },
  { id: 104, cat: 'Behavioral', company: 'Any', level: 'Senior', q: "Tell me about a time a model you shipped caused an unintended harm or introduced bias.", answer: "A content recommendation model I built was surfacing significantly fewer results for users in certain geographic markets. The training data had been collected over three years during which those markets had much lower platform penetration, so the model had learned to deprioritize them as a proxy for low engagement — not because the content was less relevant. I discovered this through a routine slice analysis when a PM asked why engagement was flat in those regions. I immediately flagged it, added geographic parity constraints to the loss function, and resampled the training data to balance geographic representation. We re-evaluated on held-out slices for all markets before redeployment. Going forward I added per-region slice metrics as mandatory evaluation gates.", whatsTested: 'Whether you own the problem, trace it to root cause (representation in training data), and implement structural fixes rather than one-time patches.', antiPattern: 'Framing this as "the data was biased, not my model." The data\'s historical bias is a known challenge — the ML engineer\'s job is to audit for it before deployment. Saying the data caused the bias without owning the failure to check for it pre-deployment signals you don\'t view fairness evaluation as part of your responsibility.' },
  { id: 105, cat: 'Behavioral', company: 'Any', level: 'Senior', q: "Tell me about a time you had to explain a model failure to non-technical leadership.", answer: "Our churn prediction model's precision dropped sharply one quarter, leading to a poorly targeted retention campaign. In the leadership review I avoided jargon entirely: I described it as \"the model was trained on behavior patterns that changed after a product redesign — it was still using the old patterns as signals.\" I showed a single chart: predicted churn rate vs actual churn rate over time, with the product release marked. I framed the fix in business terms — retrain on six months of post-redesign data — with a timeline and cost estimate. Leadership appreciated the clarity. The lesson I took away: model failures land better when framed as data staleness problems rather than algorithm problems, because the cause and fix become intuitive.", whatsTested: 'Whether you translated the technical failure into a business-language explanation and came with a fix proposal, not just a diagnosis.', antiPattern: '"I explained the AUC drop and precision-recall tradeoff to leadership." Jargon in an executive communication is a failure of communication, not a success. The interviewer is testing whether you can translate — not whether you can define metrics. Coming without a proposed fix is also wrong: leadership needs a decision to make, not a problem to contemplate.' },
  { id: 106, cat: 'Behavioral', company: 'Any', level: 'Senior', q: "Describe a time you prioritized model fairness over raw accuracy. How did you make the case for the tradeoff?", answer: "On a credit-adjacent scoring model, equalized odds analysis showed that our best-performing model (by AUC) had a false negative rate 2.4x higher for one demographic group than the overall population. Fixing this required adding fairness constraints to training — a demographic parity term in the loss function — which cost us 1.8pp AUC on aggregate. To make the case, I presented the business risk explicitly: regulatory exposure, reputational risk, and the precedent it would set for the product roadmap. I also showed that the accuracy loss translated to a difference the business couldn't measurably perceive in downstream outcomes. The team agreed to take the tradeoff. I documented the decision in the model card so future owners would understand why the final AUC wasn't higher.", whatsTested: 'Whether you quantified the fairness violation and framed the case in business risk terms — not just ethical terms.', antiPattern: '"I explained that fairness is important and we should do the right thing." Ethics arguments alone rarely move engineering teams to accept accuracy tradeoffs. The persuasive frame is regulatory risk, reputational risk, and business outcomes — paired with a quantification of how small the accuracy cost actually is. Moral arguments without business grounding are easily overruled.' },
  { id: 107, cat: 'Behavioral', company: 'Any', level: 'Senior', q: "Tell me about a time you deprecated a model that was technically working but creating hidden technical debt.", answer: "We had a gradient boosting model that had been predicting item-level inventory risk for two years. It was stable and accurate but relied on 11 hand-engineered features computed by a custom Spark job that took 6 hours to run and had no tests. Every time the upstream schema changed, the pipeline silently produced wrong feature values — we only caught this because I added PSI monitoring that flagged distribution shifts. Rather than keep patching it, I built the case for deprecation: maintenance cost per quarter, number of schema-break incidents in the last 12 months, and the risk of a silent failure in a high-stakes workflow. We replaced it with a simpler model using only features from the official feature store, with automated freshness checks. The replacement had 0.5pp lower accuracy but zero unmonitored failure modes.", whatsTested: 'Whether you built a business case for deprecation using cost and risk data — not just personal preference for cleaner code.', antiPattern: '"I refactored the code and improved the architecture." A refactor is not a deprecation story — it\'s a code change. The deprecation story must show: why the existing system was creating unseen risk, how you quantified that risk, and how you got organisational buy-in to take a short-term accuracy hit for long-term reliability. Without the buy-in mechanics, this is just a technical story.' },
  { id: 108, cat: 'Behavioral', company: 'Any', level: 'Senior', q: "Tell me about a disagreement you had with a senior engineer or scientist on model architecture. How did you resolve it?", answer: "A senior scientist on my team was convinced we needed a transformer-based architecture for a tabular fraud detection task, citing benchmark results on similar datasets. My position was that a well-tuned LightGBM with good feature engineering would match or beat it at a fraction of the inference latency and training cost. Rather than argue in the abstract, I proposed a structured comparison: both models on the same training data, same evaluation set, compared on PR-AUC, inference P99, and training time. I built the LightGBM baseline in a day; they built the transformer over a week. The results were within 0.3pp AUC, but LightGBM was 8x faster at serving and 20x cheaper to train. We shipped LightGBM. The key was making the comparison empirical rather than opinionated.", whatsTested: 'Whether you resolved the disagreement empirically (structured comparison) rather than by consensus or hierarchy.', antiPattern: '"I escalated to my manager and they sided with me." Resolving technical disagreements by escalation is a red flag. The correct resolution is an empirical comparison with pre-agreed evaluation criteria. If the senior engineer is wrong, the data should show it — not a manager\'s opinion.' },
  { id: 109, cat: 'Behavioral', company: 'Any', level: 'Senior', q: "Tell me about a time you discovered data leakage after a model was already in production.", answer: "Three weeks after deploying a lead scoring model, I noticed its offline AUC was suspiciously high — 0.94 on a problem where 0.82 had previously been considered strong. I dug into the feature pipeline and found that one feature — \"days since last contact\" — was being computed using the contact timestamp from the CRM, which was updated at the time of the outcome event, not at the time of the prediction. The model had effectively been trained on a future-timestamped feature. I immediately flagged it to the team, put the model in read-only mode while we fixed the feature computation to use point-in-time correct timestamps, and retrained. The corrected model came in at AUC 0.81. We disclosed the issue internally and added a feature lineage audit to our pre-deployment checklist.", whatsTested: 'Whether your detection signal was suspiciously high performance (not degradation) and whether you took the model offline immediately rather than waiting for a fix.', antiPattern: '"I fixed the pipeline and retrained." The critical story element is: how did you detect it? The tell is suspiciously high offline AUC — performance that\'s too good is a leakage signal. Interviewers specifically probe for whether you recognise that strong offline performance should trigger suspicion, not celebration.' },
  { id: 110, cat: 'Behavioral', company: 'Any', level: 'Senior', q: "Describe a time you had to cut scope on an ML project to meet a deadline. What did you cut and why?", answer: "On a six-week project to build a personalization model, it became clear by week three that we wouldn't have time for both the two-tower retrieval model and the ranking layer. I ran a quick expected-value analysis: the retrieval stage would surface irrelevant candidates but the ranking layer would fix most of that; a better retrieval stage without ranking would surface better candidates but score them poorly. I recommended cutting the two-tower model and replacing it with a simpler BM25 retrieval step, then focusing the remaining three weeks on a well-tuned ranking model with strong features. The ranking model drove most of the measurable quality; the retrieval was good enough as a candidate pool. We shipped on time with 80% of the intended quality improvement and planned the two-tower upgrade for the next quarter.", whatsTested: 'Whether you used an expected-value framework to choose what to cut — not just what was easiest to cut.', antiPattern: '"I cut features to meet the deadline." This is a conclusion without reasoning. The interviewer wants to see: how did you evaluate what to cut? The quality of the cut decision matters. Cutting the wrong thing can produce a worse outcome than shipping late. Showing the expected-value reasoning (which layer drives the most value?) is what makes the story senior-level.' },
  { id: 111, cat: 'Behavioral', company: 'Any', level: 'Senior', q: "Tell me about a time a retraining pipeline failed silently in production. How did you catch it and fix it?", answer: "Our weekly retraining job had been failing silently for five weeks — a schema change upstream caused the feature join to return nulls for a key feature, but the job completed without error because null imputation was filling in zeros. The model continued serving but with degraded performance. I caught it by noticing PSI drift on that feature's distribution: the serving distribution had shifted to mean ~0 while the training distribution was non-zero. A dashboard alert I'd set up on feature-level PSI flagged it after two weeks. I traced it to the schema change, fixed the join key, added a data quality assertion that would fail the pipeline if null rate on any key feature exceeded 5%, and added an alert for training job completion that validated output model performance against a held-out baseline. Silent failures require explicit validation gates — completing the job is not enough.", whatsTested: 'Whether you describe the detection mechanism (PSI monitoring on feature distributions) and the structural fix (data quality gates) — not just "I found the bug."', antiPattern: '"I set up logging so I could debug it." Logging shows you what happened after you\'re already investigating. What catches silent failures is monitoring with alerts: PSI thresholds on feature distributions, null rate assertions that fail the pipeline, and model performance validation against a baseline on every retrain. Logging is forensics; monitoring is prevention.' },
  { id: 112, cat: 'Behavioral', company: 'Any', level: 'Senior', q: "Describe a time you had to balance speed-to-ship against model quality. What was the context and how did you decide?", answer: "We had a new market launching in three weeks and needed a pricing model. Building a full price elasticity model with demand forecasting would have taken six weeks. The tradeoff I proposed: ship a rules-based pricing baseline at launch (competitor-anchored with simple floor/ceiling logic), instrument everything for data collection, and build the ML model on the first four weeks of production data. The rules-based baseline was worse in absolute quality but it was correct-by-construction and generated the ground truth labels we needed to train the ML model properly. The ML model shipped five weeks post-launch and outperformed the baseline by 12% on revenue per transaction. Shipping a bad ML model at launch would have been worse than a transparent heuristic — at least the heuristic failure modes were understood.", whatsTested: 'Whether you show that you used a deliberate data strategy (heuristic baseline to collect ground truth labels) rather than just "shipped a simpler model."', antiPattern: '"I built a simple logistic regression instead of a complex model to meet the deadline." Logistic regression trained without ground truth labels has the same problem as a complex model — you don\'t have the data yet. The insight in this story is: a rules-based baseline is the right v1 because it\'s correct-by-construction and generates the labels the ML model needs. That\'s a strategic choice, not just a scope reduction.' },
  { id: 113, cat: 'Behavioral', company: 'Any', level: 'Senior', q: "Tell me about a time you worked with a team that had low ML maturity. How did you move them forward?", answer: "I joined a data team that was using Excel-based forecasting and had no experimentation infrastructure. Rather than push for an ML platform overhaul, I started with the smallest credible win: replaced one manual forecast with a prophet model, showed it reduced MAE by 30%, and deployed it in a Jupyter notebook run by a cron job. That built enough trust to justify standing up MLflow for experiment tracking. Over three months I introduced: (1) a shared feature store in a dbt project they already used, (2) a model evaluation template with standard metrics, (3) a shadow deployment pattern using a feature flag in their existing API. Each step reused infrastructure they already trusted. By month six they were running A/B tests on model changes. The key was meeting the team where they were, not where I thought they should be.", whatsTested: 'Whether you started with a win rather than a platform pitch — and whether each step built on infrastructure the team already trusted.', antiPattern: '"I introduced proper ML engineering practices to the team." This is a conclusion without a change management strategy. The interviewer is testing whether you understand that organisational change requires credibility-building (small wins), incremental adoption, and meeting people where they are — not a comprehensive rollout of best practices.' },
  { id: 114, cat: 'Behavioral', company: 'Any', level: 'Senior', q: "Tell me about a time a model underperformed for a specific user segment. How did you handle the discovery and the fix?", answer: "Aggregate metrics on our recommendation model looked healthy — NDCG@10 was up 4% — but a quarterly slice analysis revealed that new users (< 30 days on platform) had a 19% lower click rate on recommendations than the previous model. The root cause: the new model used a 90-day activity feature that was null for new users, and null imputation with zero was causing the model to systematically rank popular-but-irrelevant items for them. I added a user-tenure feature and split the imputation strategy: for users with < 14 days of history, I switched to a content-based fallback that used item metadata rather than interaction history. We also added new-user performance as a mandatory evaluation slice going forward. Post-fix, new user recommendation CTR recovered to parity within two weeks. Aggregate metrics can mask segment failures — always disaggregate before calling a model healthy.", whatsTested: 'Whether you trace the root cause to a specific feature-imputation interaction (not just "the model didn\'t generalise") and whether you added a structural fix (mandatory new-user evaluation slice) rather than just patching this instance.', antiPattern: '"I noticed the model performed worse for new users and added more data." More data doesn\'t fix a null-imputation issue that systematically pushes all new users to the same popular items. The diagnosis must be precise: which feature was null, what did imputation do to it, and what did the model learn from the imputed value.' },
  { id: 115, cat: 'Behavioral', company: 'Any', level: 'Senior', q: "Tell me about a time a stakeholder wanted a feature the model said was unimportant. How did you handle it.", answer: "A senior PM insisted we include \"account age\" as a feature in a churn model, citing intuition from years of experience. SHAP analysis showed it had near-zero marginal contribution after conditioning on behavioral features — the signal it carried was already captured by session frequency and recency. Rather than dismiss the request, I ran an ablation: model with and without account age on a held-out validation set. The difference was 0.1pp AUC — not measurable. I showed the PM both the SHAP values and the ablation result, and acknowledged that his intuition was right directionally (older accounts do churn less) but the behavioral features were already encoding that signal more precisely. He accepted this once he understood the model wasn't ignoring the insight, just capturing it through a different path. Ablations are more persuasive than feature importance plots alone.", whatsTested: 'Whether you validated the stakeholder\'s intuition before dismissing it, and whether you used an ablation (not just SHAP) to make the empirical case.', antiPattern: '"I showed the PM the SHAP values and explained they were low." SHAP alone is often insufficient — PMs don\'t have the statistical background to evaluate SHAP magnitude. The ablation is the persuasive evidence: "I ran the model with and without this feature on held-out data and the difference was 0.1pp." That\'s language anyone understands.' },
  { id: 116, cat: 'Statistics', company: 'Any', level: 'Senior', q: "What is a power analysis and how do you run one before launching an A/B test?", answer: "Power analysis determines the sample size needed to detect a given effect with specified statistical power and significance level. Inputs: (1) Baseline metric value and its variance (estimate from historical data). (2) Minimum detectable effect (MDE) — the smallest lift you care about. (3) Significance level α (typically 0.05). (4) Desired power 1-β (typically 0.80 or 0.90). Formula for two-proportion test: n = 2 × (z_α/2 + z_β)² × p(1-p) / MDE². Python: statsmodels.stats.proportion.proportion_effectsize + zt_ind_solve_power. Practical advice: MDE should be business-driven (what effect would change a decision?), not statistical-driven (what can we detect?). If required n > monthly active users, either wait, reduce traffic split, or accept lower power. Common mistake: running the power analysis after seeing the data and then declaring the experiment adequately powered.", whatsTested: 'Whether you state that MDE must be chosen for business reasons before computing sample size — and whether you name the "run analysis after seeing data" mistake explicitly.', antiPattern: '"I\'d run the experiment and then do the power analysis to confirm we had enough data." Post-hoc power analysis is meaningless — it will always show you had enough power when the result was significant, by mathematical construction. Power analysis is a pre-commitment tool. Running it after is p-hacking dressed up as rigor.' },
  { id: 117, cat: 'Statistics', company: 'Airbnb', level: 'Senior', q: "Explain the delta method and when you need it for A/B test metric variance estimation.", answer: "The delta method approximates the variance of a nonlinear function of random variables using a first-order Taylor expansion. When you need it: metrics that are ratios of random variables — revenue per user = total_revenue / users, CTR = clicks / impressions. Both numerator and denominator are random, so standard variance formulas don't apply directly. Formula: if Y = f(X), then Var(Y) ≈ (f'(μ))² × Var(X). For ratio metric r = X/Y: Var(r) ≈ (1/μ_Y)² × Var(X) + (μ_X/μ_Y²)² × Var(Y) - 2(μ_X/μ_Y³) × Cov(X,Y). Bootstrap alternative: if data fits in memory, bootstrap the ratio metric directly — simpler and doesn't require the Taylor approximation. In practice: Booking.com, LinkedIn, and Airbnb all use the delta method for ratio metrics. If you use a naive variance estimate (treating the ratio as fixed), your confidence intervals will be wrong and your p-values unreliable.", whatsTested: 'Whether you identify ratio metrics as the specific case that requires the delta method, and whether you know the bootstrap as a practical alternative.', antiPattern: '"Standard variance formulas work for CTR — it\'s just a proportion." CTR = clicks / impressions, where both are random variables. Treating it as a fixed-denominator proportion assumes impressions are non-random (fixed), which is only valid if all users see the same number of impressions. In practice, impressions vary per user, making the ratio a delta-method problem.' },
  { id: 118, cat: 'Statistics', company: 'Google', level: 'Staff', q: "What is a permutation test and when would you use it instead of a t-test?", answer: "Permutation test: under the null hypothesis (no treatment effect), the labels 'control' and 'treatment' are exchangeable. Randomly shuffle group assignments many times (10,000+), compute the test statistic each time to build a null distribution, then compute the p-value as the fraction of permutations with statistic >= observed. No distributional assumptions required. Use permutation test instead of t-test when: (1) Metric distribution is highly non-normal (heavy tails, bimodal) and sample size is small (CLT hasn't kicked in). (2) Custom test statistic (e.g., median difference, ratio of quantiles) for which no parametric distribution is known. (3) Dependence structure is complex. Use t-test when: large samples (CLT handles non-normality), speed matters (t-test is O(n), permutation is O(n × permutations)). In practice: for large-scale web experiments, t-tests are fine due to large n. Permutation tests matter for small n or unusual metrics.", whatsTested: 'Whether you know that permutation tests are not universally better than t-tests — and that CLT makes t-tests valid at large n regardless of distribution.', antiPattern: '"I\'d always use a permutation test because it makes fewer assumptions." Fewer assumptions comes at a computational cost: 10,000+ model evaluations vs one. At large n (millions of web users), the t-test\'s normality assumption is covered by CLT and the t-test is millions of times faster. Using a permutation test by default on large web experiments is over-engineering.' },
  { id: 119, cat: 'Evaluation', company: 'Any', level: 'Senior', q: "How do you design an offline evaluation framework for a multi-label classification model?", answer: "Multi-label: each example can have zero or more labels. Standard binary metrics don't apply directly. Key metrics: (1) Micro-averaged F1: aggregate TP, FP, FN across all labels, then compute F1. Dominated by frequent labels. Use when overall performance matters. (2) Macro-averaged F1: compute F1 per label, then average. Equal weight per label regardless of frequency. Use when rare label performance matters. (3) Subset accuracy (Exact Match Ratio): fraction of examples where predicted label set exactly equals true label set. Very strict — useful for structured output tasks. (4) Hamming loss: fraction of (example, label) pairs that are incorrectly predicted. Lenient. (5) PR curve per label: for high-stakes labels, inspect per-label threshold independently. Framework design: store per-label metrics in a results matrix, always report micro/macro split, define which labels are 'critical' and require minimum per-label recall. Monitor per-label performance in production — aggregate metrics can hide a label that degrades entirely.", whatsTested: 'Whether you distinguish micro vs macro averaging and explain when each is appropriate — not just list them.', antiPattern: '"I\'d use macro-averaged F1 to handle class imbalance." Macro-averaging gives equal weight to every label regardless of frequency — which means a model that performs perfectly on 99 common labels but fails on one rare label still gets a high macro-F1. Whether macro or micro is appropriate depends entirely on whether rare label performance matters for the use case.' },
  { id: 120, cat: 'Evaluation', company: 'Meta', level: 'Senior', q: "What is a surrogate metric and what are the risks of optimizing for one?", answer: "A surrogate metric is a measurable proxy that stands in for the true north-star metric when the north-star is slow, expensive, or impossible to measure directly. Examples: CTR as a surrogate for user value, AUC as a surrogate for revenue, NLP BLEU score as a surrogate for translation quality. Risks: (1) Surrogate-north-star divergence: optimizing the surrogate moves the surrogate up but the north-star flat or down. Goodhart's law — 'When a measure becomes a target, it ceases to be a good measure.' (2) Surrogate can be gamed: a model finds artifacts in the proxy that don't reflect real improvement. (3) Measurement frequency bias: optimizing for an easily-measured short-term metric can harm long-term value. Mitigations: (1) Validate surrogates periodically by running experiments where you can measure both surrogate and north-star. (2) Use multiple surrogates to triangulate. (3) Run occasional long-window experiments where the north-star is measurable. (4) Monitor for surrogate-north-star divergence in production.", whatsTested: 'Whether you name Goodhart\'s Law and can give a concrete example of surrogate-north-star divergence — not just abstract risks.', antiPattern: '"Surrogate metrics are fine as long as they correlate with the north-star." Correlation at baseline doesn\'t guarantee correlation under optimisation pressure. The problem is that optimising the surrogate changes the data distribution — and the historical correlation may not hold in the new distribution. This is Goodhart\'s Law and it requires active monitoring, not an assumption of stability.' },
  { id: 121, cat: 'Evaluation', company: 'Any', level: 'Staff', q: "How do you build an evaluation framework for an ML system that has no ground truth labels at serving time?", answer: "This is the unsupervised or delayed-label serving scenario — common in anomaly detection, content generation, and recommendations. Strategies: (1) Proxy signals: use implicit feedback as a label proxy. For recommendations: clicks, watch time, saves, shares. Design and validate which proxy correlates with the true objective (run a labeling study to calibrate). (2) Human evaluation: periodic sampling with human labelers. Build a labeling guideline, measure inter-annotator agreement (Cohen's kappa). Use as ground truth for calibrating automated metrics. (3) LLM-as-judge: for generative outputs, use a strong LLM to rate outputs on defined rubrics. Validate judge correlates with human ratings before relying on it. (4) Behavioral tests (invariance testing): apply known-good transformations (e.g., paraphrase an input) and check the model output changes appropriately. Catches regressions without needing labels. (5) Canary sets: maintain a small labeled evaluation set, update quarterly, use it for regression detection in CI/CD. Key principle: define the evaluation framework before deploying — retrofitting it after is much harder.", whatsTested: 'Whether you have a multi-layer answer (proxy signals + periodic human eval + regression tests) rather than a single mechanism.', antiPattern: '"I\'d monitor user satisfaction signals like clicks and saves as proxies." Proxy signals alone are insufficient — a model can game implicit feedback (e.g., clickbait recommendations get high clicks but low satisfaction). The framework needs at least one human calibration layer and a regression test set to catch degradation that proxies miss.' },
  { id: 122, cat: 'System Design', company: 'Google', level: 'Staff', q: "Design a real-time bidding (RTB) system for programmatic advertising — focus on the ML components.", answer: "Real-time bidding: an auction runs in <100ms to decide which ad to show for each page load. ML components: (1) Click-through rate (CTR) prediction: predict P(click | user, ad, context). Features: user segment, ad category, page context, recency, device. Model: logistic regression or LightGBM (sub-millisecond inference). Calibration critical: bid = value × P(click) — miscalibration directly misobids. (2) Conversion rate (CVR) prediction: P(convert | click) for downstream value estimation. Delayed labels (conversions happen hours later) — use attribution windows and partial labels. (3) Bid price optimization: combine CTR, CVR, and advertiser value per conversion into a bid. Account for second-price auction mechanics. (4) Budget pacing: control spend rate across the day — ML model predicts bid landscape to pace evenly (not just throttle randomly). Serving constraints: entire pipeline <10ms. Model size: must fit in L2/L3 cache. Feature freshness: user segment refreshed every few hours. Monitoring: win rate, CPM trends, CTR vs predicted CTR calibration curve daily.", whatsTested: 'Whether you immediately identify calibration as critical (bid = value × P(click), so miscalibration = systematic overbidding or underbidding) and whether you think about CVR label delay.', antiPattern: '"I\'d optimise for CTR since that\'s what advertisers pay for." Advertisers pay for conversions (CPA) or value (CPC/CPM) — not raw CTR. A CTR-optimised model that bids high on users who click but never buy will spend advertiser budgets without delivering conversions. The bid formula connects CTR × CVR × value — optimising only CTR gets one-third of the equation.' },
  { id: 123, cat: 'System Design', company: 'Amazon', level: 'Staff', q: "Design a demand forecasting system for a large e-commerce warehouse with 5M SKUs.", answer: "Scale: 5M SKUs × daily forecasts = ~5M predictions per day. No single global model works at this scale without hierarchical structure. Architecture: (1) Hierarchical forecasting: forecast at category → subcategory → SKU level. Use reconciliation (bottom-up, top-down, or optimal combination via MinT) to ensure consistency across levels. (2) Models by tier: top SKUs (80% of volume, ~50K items): individual models or LightGBM with rich features. Mid tier (next 500K): global model with item embeddings. Long tail (4.5M+ items): simple statistical baselines (seasonal naive, exponential smoothing). (3) Features: historical sales, price, promotions, seasonality (Fourier terms), competitor price, days-since-listing, inventory level. (4) Intermittent demand (sparse sales): Croston's method or zero-inflated models for SKUs with < 1 sale/week. (5) Uncertainty quantification: use quantile regression or conformal prediction — buying teams need P10/P50/P90 intervals, not just point forecasts. (6) Retraining: weekly for most; daily for top SKUs during peak (holiday season). Monitoring: MAPE by tier, forecast bias (are we systematically over/under-stocking?), stockout rate and overstock rate as downstream business KPIs.", whatsTested: 'Whether you tier the model strategy by SKU volume (one approach for top SKUs, another for long tail) and whether you provide uncertainty intervals — not just point forecasts.', antiPattern: '"I\'d train a single LSTM or TFT model on all 5M SKUs." A single model for all SKUs treats a top-50K SKU the same as a long-tail SKU with 2 sales per year — they require different modelling approaches. Also: buying teams cannot act on point forecasts alone. They need P10/P90 intervals to make safety stock decisions. Point-forecast-only is an incomplete design.' },
  { id: 124, cat: 'Trees & Ensembles', company: 'Any', level: 'Senior', q: "How does gradient boosting build trees and what is the role of the residuals?", answer: "Gradient boosting trains trees sequentially. At each step t: (1) Compute pseudo-residuals: the negative gradient of the loss function evaluated at the current model prediction. For MSE loss: residuals = y - F_{t-1}(x). For log-loss: residuals are more complex (related to probability error). (2) Fit a shallow tree to predict the residuals. (3) Add the tree to the ensemble: F_t(x) = F_{t-1}(x) + learning_rate × h_t(x). Intuition: each tree corrects what the previous ensemble got wrong — not the original target, but the remaining error signal. XGBoost extends this: uses second-order Taylor expansion of the loss (Hessian in addition to gradient) to compute exact optimal leaf weights analytically. This is why XGBoost converges faster than sklearn GBM. Key implication: gradient boosting is sensitive to outliers in regression tasks (outliers dominate the MSE gradient). Mitigation: use Huber loss or quantile loss, which are robust to outliers. Or clip residuals by percentile before fitting each tree.", whatsTested: 'Whether you explain that each tree fits the residuals (negative gradient), not the original target — and whether you connect outlier sensitivity to the MSE gradient.', antiPattern: '"Each tree corrects the errors of previous trees." True but imprecise. The key is the mechanism: trees fit the negative gradient of the loss, which for MSE is exactly the residual. For other losses (log-loss, Huber), it\'s the negative gradient of that loss — not simply "the errors." Understanding this distinction matters when choosing the right loss for your problem.' },
  { id: 125, cat: 'Trees & Ensembles', company: 'Any', level: 'Mid', q: "What is out-of-bag (OOB) error in Random Forest and when is it a valid substitute for cross-validation?", answer: "OOB error: each tree in a Random Forest is trained on a bootstrap sample (~63% of the data). The remaining ~37% (out-of-bag samples) act as a validation set for that tree. OOB error averages predictions from all trees where a given sample was OOB — gives a nearly unbiased estimate of generalisation error without a separate validation split. Valid substitute for CV when: (1) Dataset is large enough that each sample is OOB for enough trees (rule of thumb: n_estimators >= 100). (2) Data is IID (not time-series — OOB violates temporal ordering). (3) You need a quick estimate without the cost of k×model fits. Not a valid substitute when: (4) Data has temporal or group structure — OOB sampling ignores this, leaking future data or within-group patterns. (5) You need to tune hyperparameters — OOB estimates of different hyperparameter settings are not independent and can lead to over-optimistic selection. In practice: OOB is useful for quick sanity checks, but for final model evaluation and hyperparam tuning, use proper k-fold or time-series CV.", whatsTested: 'Whether you name the time-series failure mode (OOB violates temporal ordering) and the hyperparameter tuning failure mode (OOB estimates are not independent across hyperparameter settings).', antiPattern: '"OOB error is equivalent to cross-validation for Random Forest." For IID data and model comparison, OOB is a good approximation. But for hyperparameter tuning, OOB estimates of different settings are correlated in ways that cross-validation folds are not. Using OOB for hyperparameter selection can lead to over-optimistic results that don\'t hold on a true held-out set.' },
  { id: 126, cat: 'SQL', company: 'Any', level: 'Senior', q: "Write a SQL query to detect training-serving skew by comparing feature distributions across two tables.", answer: "Compare mean, stddev, null rate, and a bucketed histogram for a numeric feature between training and serving samples:\nWITH train_stats AS (\n  SELECT\n    AVG(feature_val) AS train_mean,\n    STDDEV(feature_val) AS train_std,\n    COUNTIF(feature_val IS NULL) / COUNT(*) AS train_null_rate\n  FROM training_features\n),\nserving_stats AS (\n  SELECT\n    AVG(feature_val) AS serve_mean,\n    STDDEV(feature_val) AS serve_std,\n    COUNTIF(feature_val IS NULL) / COUNT(*) AS serve_null_rate\n  FROM serving_features\n  WHERE request_ts >= CURRENT_TIMESTAMP - INTERVAL 24 HOUR\n)\nSELECT\n  t.train_mean, s.serve_mean,\n  ABS(t.train_mean - s.serve_mean) / NULLIF(t.train_std, 0) AS std_shift,\n  t.train_null_rate, s.serve_null_rate,\n  ABS(t.train_null_rate - s.serve_null_rate) AS null_rate_delta\nFROM train_stats t CROSS JOIN serving_stats s\nAlert when: std_shift > 1.0 (mean shifted by >1 std dev) or null_rate_delta > 0.05. This is a lightweight PSI proxy in pure SQL — no Python required for the first-pass skew check.", whatsTested: 'Whether you check null_rate as a separate signal (not just distribution moments) and whether you use NULLIF to prevent division by zero on std_shift.', antiPattern: 'Comparing only means: `SELECT AVG(feature_val) FROM training WHERE ... vs serving WHERE ...`. Mean comparison alone misses the null_rate delta (a schema change might produce nulls without changing the non-null mean) and misses distribution shape changes that leave the mean unchanged. At minimum, compare mean + stddev + null_rate.' },
  { id: 127, cat: 'Features', company: 'Any', level: 'Staff', q: "How do you version features in a feature store to support reproducible model training?", answer: "Feature versioning is the practice of treating feature definitions as code artifacts with explicit versions so that any training run can reproduce the exact feature values used. What must be versioned: (1) Feature transformation logic (the SQL/Python code that computes the feature). (2) Feature backfill snapshot (the actual values in the offline store at training time). (3) Feature metadata (data type, expected range, owner, lineage to source table). Implementation: (1) Hash-based versioning: hash the transformation code + source table schema. If either changes, the hash changes. Store mapping: feature_name + hash → offline table partition. (2) Timestamp-based: each feature has a 'computed_at' timestamp; training jobs record which timestamp they used. (3) Model lineage: the model artifact stores a manifest of {feature_name: version_hash} for every feature it was trained on. Why it matters: without feature versioning, a schema change upstream silently changes what a feature means — models trained before and after are not comparable. Debugging production issues 6 months later requires being able to reproduce the training data exactly. Costs: storage (multiple versions of large feature tables), operational overhead (deprecating old versions). Mitigation: TTL-based cleanup — keep last 3 versions, or versions used by any model in the registry.", whatsTested: 'Whether you version both the transformation logic AND the backfill snapshot — versioning only the code is insufficient if the source data has changed.', antiPattern: '"I\'d version control the feature transformation code in Git." Git versioning tracks the code but not the data state. A feature with the same transformation code applied to a different source table snapshot produces different values. True feature versioning requires both: the code version AND a snapshot of the computed values at training time.' },
  { id: 128, cat: 'Regression', company: 'Any', level: 'Senior', q: "How do you approach a regression problem where the target is highly right-skewed (e.g., revenue, lifetime value)?", answer: "Right-skewed targets create problems for OLS: residuals are non-normal, a few large values dominate the MSE loss, and the model may overfit to outliers. Options: (1) Log-transform the target: fit on log(y), predict log(y_hat), back-transform with exp(y_hat). Handles multiplicative relationships well. Caveat: back-transforming gives the median, not the mean — add a smearing correction (Duan's smearing estimator) if you need E[y] not median. (2) Use a model with a natural right-skew assumption: Gamma regression (for positive continuous targets with multiplicative variance), Tweedie regression (for mix of zeros and positives — e.g., insurance claims). (3) Quantile regression: predict P50 (or any quantile) directly. Robust to outliers, no back-transform bias. Use L1 loss (absolute value, which minimises the median). (4) Robust loss: Huber loss — behaves like MSE for small residuals, MAE for large ones. Reduces influence of outliers without throwing them away. (5) Winsorise the target at a high percentile (e.g., 99th), train on winsorised values, accept that you're modelling the typical case and not extreme tails. Practical advice: always plot residual distribution before choosing. Log-transform + linear model often beats a complex model on a raw skewed target.", whatsTested: 'Whether you name the back-transform bias (exp of log-mean ≠ mean of exp) and whether you know when log-transform is the right choice vs quantile regression.', antiPattern: '"I\'d log-transform the target and back-transform the predictions with exp()." This is almost correct but misses the Jensen\'s inequality bias: E[exp(log_y_hat)] ≠ exp(E[log_y_hat]). Back-transforming with exp() gives a prediction of the median, not the mean. For revenue or LTV where you need the expected value (not the typical case), you need Duan\'s smearing correction or a distributional model.' },
]

