// ─── Fluency Drills Component ─────────────────────────────────────────────────
function FluencyDrills() {
  const [idx,      setIdx]      = useState(0)
  const [revealed, setRevealed] = useState(false)
  const drill = FLUENCY_DRILLS[idx]

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '20px' }}>
      <div style={{ display: 'flex', alignItems: 'flex-start', justifyContent: 'space-between', flexWrap: 'wrap', gap: '12px' }}>
        <div>
          <div className="section-eyebrow" style={{ marginBottom: '4px' }}>Fluency Drills</div>
          <p style={{ fontSize: '13px', color: 'var(--ink-low)', margin: 0, lineHeight: 1.5 }}>Replace weak phrases with the production-grade equivalent. {FLUENCY_DRILLS.length} drills.</p>
        </div>
        <span style={{ fontSize: '12px', color: 'var(--ink-low)', fontFamily: 'var(--font-mono)', paddingTop: '4px' }}>{idx + 1} / {FLUENCY_DRILLS.length}</span>
      </div>

      {/* Weak phrase card */}
      <div style={{ padding: '24px 28px', background: 'rgba(240,165,0,0.08)', border: '1px solid rgba(240,165,0,0.20)', borderRadius: '12px' }}>
        <div style={{ fontSize: '10px', color: 'var(--ink-low)', textTransform: 'uppercase', letterSpacing: '0.07em', fontFamily: 'var(--font-mono)', marginBottom: '10px' }}>Weak phrase</div>
        <p style={{ fontFamily: 'var(--font-sans)', fontSize: '17px', color: 'var(--ink-mid)', lineHeight: 1.5, margin: 0 }}>"{drill.weak}"</p>
      </div>

      {!revealed ? (
        <button className="btn-primary" style={{ alignSelf: 'flex-start' }} onClick={() => setRevealed(true)}>Reveal strong phrase →</button>
      ) : (
        <>
          <div className="msl-reveal-panel" style={{ padding: '24px 28px' }}>
            <div className="section-eyebrow" style={{ marginBottom: '10px' }}>Strong phrase</div>
            <p style={{ fontFamily: 'var(--font-sans)', fontSize: '16px', color: 'var(--ink-hi)', lineHeight: 1.55, margin: 0, marginBottom: '16px' }}>"{drill.strong}"</p>
            <div style={{ paddingTop: '14px', borderTop: '1px solid rgba(52,211,153,0.15)' }}>
              <div style={{ fontSize: '10px', color: 'var(--prime)', textTransform: 'uppercase', letterSpacing: '0.07em', fontFamily: 'var(--font-mono)', marginBottom: '6px' }}>Why it matters</div>
              <p style={{ fontSize: '13px', color: 'var(--ink-mid)', lineHeight: 1.7, margin: 0 }}>{drill.why}</p>
            </div>
          </div>
          <div style={{ display: 'flex', gap: '10px', flexWrap: 'wrap' }}>
            <button className="btn-primary"
              onClick={() => { setIdx(i => Math.min(i + 1, FLUENCY_DRILLS.length - 1)); setRevealed(false) }}
              disabled={idx === FLUENCY_DRILLS.length - 1}>
              Next drill →
            </button>
            <button className="btn-ghost" onClick={() => { setIdx(0); setRevealed(false) }}>↺ Restart</button>
          </div>
        </>
      )}

      {/* Dot progress */}
      <div style={{ display: 'flex', gap: '5px', flexWrap: 'wrap', paddingTop: '4px' }}>
        {FLUENCY_DRILLS.map((_, i) => (
          <button key={i} onClick={() => { setIdx(i); setRevealed(false) }}
            title={`Drill ${i + 1}`}
            style={{ width: '8px', height: '8px', borderRadius: '50%', background: i < idx ? 'var(--prime)' : i === idx ? 'var(--prime)' : 'var(--rim)', border: 'none', cursor: 'pointer', padding: 0, flexShrink: 0 }} />
        ))}
      </div>
    </div>
  )
}

// ─── Behavioral Scenarios Component ──────────────────────────────────────
function BehavioralScenarios() {
  const [answers, setAnswers] = useState({})

  useEffect(() => {
    const saved = localStorage.getItem('msl_score:behavioral')
    if (saved) setAnswers(JSON.parse(saved))
  }, [])

  useEffect(() => {
    localStorage.setItem('msl_score:behavioral', JSON.stringify(answers))
  }, [answers])

  const handleAnswer = (scenarioId, option) => {
    setAnswers(prev => ({ ...prev, [scenarioId]: option }))
  }

  const score = BEHAVIORAL_SCENARIOS.filter(s => answers[s.id] === s.correct).length

  return (
    <div style={{ maxWidth: 860, margin: '0 auto', padding: '24px 16px' }}>
      <div style={{ marginBottom: 24 }}>
        <h2 style={{ fontFamily: 'var(--font-sans)', fontWeight: 700, fontSize: 22, color: 'var(--ink-hi)', margin: '0 0 4px' }}>
          Behavioral Scenarios
        </h2>
        <p style={{ fontFamily: 'var(--font-sans)', fontSize: 14, color: 'var(--ink-mid)', margin: '0 0 4px' }}>
          {BEHAVIORAL_SCENARIOS.length} ML-specific behavioral judgment questions. Real situations, right and wrong approaches.
        </p>
        <p style={{ fontSize: '13px', color: 'var(--ink-low)', lineHeight: 1.5, margin: 0, fontFamily: 'var(--font-sans)' }}>
          Metric disagreements with stakeholders. Silent model degradation. Balancing deadline pressure with rigor. Architecture decisions. Production incidents while on holiday.
        </p>
      </div>

      <div style={{ display: 'flex', alignItems: 'center', gap: 16, background: 'var(--depth)', border: '1px solid var(--rim)', borderRadius: 8, padding: '12px 16px', marginBottom: 20, flexWrap: 'wrap' }}>
        <div style={{ fontFamily: 'var(--font-mono)', fontSize: 28, fontWeight: 700, color: 'var(--prime)', lineHeight: 1 }}>
          {score}
          <span style={{ fontSize: 16, color: 'var(--ink-ghost)', fontWeight: 400 }}>/{BEHAVIORAL_SCENARIOS.length}</span>
        </div>
        <div style={{ flex: '1 1 auto', minWidth: 160 }}>
          <div style={{ fontFamily: 'var(--font-sans)', fontSize: 13, fontWeight: 600, color: 'var(--ink-hi)' }}>
            Correct answers
          </div>
          <div style={{ fontFamily: 'var(--font-sans)', fontSize: 12, color: 'var(--ink-low)' }}>
            {Object.keys(answers).length} of {BEHAVIORAL_SCENARIOS.length} answered
          </div>
        </div>
        {Object.keys(answers).length > 0 && (
          <div style={{ marginLeft: 'auto', minWidth: 100 }}>
            <div style={{ background: 'var(--surface)', borderRadius: 4, height: 6, width: 100, overflow: 'hidden' }}>
              <div style={{ height: '100%', width: `${(score / BEHAVIORAL_SCENARIOS.length) * 100}%`, background: 'var(--prime)', borderRadius: 4, transition: 'width 0.4s ease' }} />
            </div>
            <div style={{ fontFamily: 'var(--font-sans)', fontSize: 11, color: 'var(--ink-ghost)', marginTop: 3, textAlign: 'right' }}>
              {Math.round((score / BEHAVIORAL_SCENARIOS.length) * 100)}%
            </div>
          </div>
        )}
      </div>

      <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
        {BEHAVIORAL_SCENARIOS.map(scenario => {
          const answered = answers[scenario.id]
          const isCorrect = answered === scenario.correct
          const bgColor = 'rgba(240,165,0,0.08)'
          const borderColor = 'rgba(240,165,0,0.20)'

          return (
            <div key={scenario.id} className="card" style={{ padding: '20px', overflow: 'hidden', border: `1px solid ${borderColor}`, background: bgColor }}>
              <div style={{ marginBottom: '14px' }}>
                <p style={{ fontSize: 15, fontWeight: 600, color: 'var(--ink-hi)', lineHeight: 1.6, margin: 0, marginBottom: '12px' }}>
                  {scenario.q}
                </p>

                <div style={{ display: 'flex', flexDirection: 'column', gap: '7px' }}>
                  {Object.entries(scenario.options).map(([key, text]) => (
                    <button
                      key={key}
                      className={`msl-option-btn${answered && key === scenario.correct ? ' correct' : answered && key === answered ? ' wrong' : ''}`}
                      style={{ marginBottom: 0, cursor: answered ? 'default' : 'pointer' }}
                      onClick={() => !answered && handleAnswer(scenario.id, key)}
                      disabled={answered}
                    >
                      <span style={{ fontFamily: 'var(--font-mono)', fontWeight: 700, marginRight: 8, color: answered && key === scenario.correct ? 'var(--mint)' : answered && key === answered ? 'var(--rose)' : 'var(--ink-ghost)' }}>
                        {key})
                      </span>
                      {text}
                    </button>
                  ))}
                </div>
              </div>

              {answered && (
                <div className="msl-reveal-panel" style={{ marginTop: '14px', paddingTop: '14px', borderTop: '1px solid rgba(240,165,0,0.20)' }}>
                  <div style={{ fontSize: 11, fontWeight: 700, color: 'var(--prime)', textTransform: 'uppercase', letterSpacing: '0.06em', marginBottom: '8px' }}>
                    {isCorrect ? 'Correct' : 'Wrong'} — {scenario.correct}
                  </div>
                  <p style={{ fontSize: 13, color: 'var(--ink-mid)', lineHeight: 1.7, margin: 0, marginBottom: '10px' }}>
                    {scenario.explanation[scenario.correct]}
                  </p>
                  {scenario.explanation[answered] && answered !== scenario.correct && (
                    <>
                      <div style={{ fontSize: 11, fontWeight: 700, color: 'var(--rose)', textTransform: 'uppercase', letterSpacing: '0.06em', marginBottom: '8px', marginTop: '10px' }}>
                        Why {answered} is wrong
                      </div>
                      <p style={{ fontSize: 13, color: 'var(--ink-mid)', lineHeight: 1.7, margin: 0 }}>
                        {scenario.explanation[answered]}
                      </p>
                    </>
                  )}
                </div>
              )}
            </div>
          )
        })}
      </div>
    </div>
  )
}

// ─── Timed Practice Mode ─────────────────────────────────────────────────────
function TimedPractice({ questions, onExit }) {
  const DURATION = 45 * 60
  const [idx,          setIdx]          = useState(0)
  const [revealed,     setRevealed]     = useState(false)
  const [elapsed,      setElapsed]      = useState(0)
  const [tierSelected, setTierSelected] = useState(null)
  const [tierHistory,  setTierHistory]  = useState([])
  const [hoveredTier,  setHoveredTier]  = useState(null)
  const timerRef = useRef(null)

  useEffect(() => {
    timerRef.current = setInterval(() => setElapsed(e => e + 1), 1000)
    return () => clearInterval(timerRef.current)
  }, [])

  const q = questions[idx]
  const cc = CAT_COLORS[q?.cat] || CAT_COLORS['Architecture']
  const remaining = DURATION - elapsed
  const mins = Math.floor(Math.abs(remaining) / 60)
  const secs = Math.abs(remaining) % 60
  const overtime = remaining < 0
  const isLast = idx === questions.length - 1

  function nextQ() {
    setIdx(i => Math.min(i + 1, questions.length - 1))
    setRevealed(false)
    setTierSelected(null)
  }

  // Summary screen
  if (isLast && tierSelected) {
    recordInterviewSessionMastery(tierHistory)
    const counts = TIER_LEVELS.map(t => ({ ...t, n: tierHistory.filter(h => h.tier === t.key).length }))
    const topTier = [...tierHistory].reverse().find(h => h.tier)
    const topTierObj = TIER_LEVELS.slice().reverse().find(t => tierHistory.some(h => h.tier === t.key))
    return (
      <div style={{ display: 'flex', flexDirection: 'column', gap: '20px' }}>
        <div style={{ padding: '28px', background: 'rgba(52,211,153,0.13)', border: '1px solid rgba(52,211,153,0.25)', borderRadius: '12px' }}>
          <div className="section-eyebrow" style={{ marginBottom: '10px' }}>Session complete</div>
          <div style={{ fontFamily: 'var(--font-sans)', fontSize: '22px', fontWeight: 700, color: 'var(--ink-hi)', marginBottom: '4px' }}>
            {questions.length} questions · {Math.floor(elapsed/60)}m {elapsed%60}s
          </div>
          <p style={{ fontSize: '13px', color: 'var(--ink-mid)', margin: 0 }}>Self-assessment breakdown:</p>
        </div>
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(2,1fr)', gap: '10px' }}>
          {counts.map(t => (
            <div key={t.key} style={{ padding: '16px 18px', background: 'linear-gradient(160deg, rgba(255,255,255,0.10) 0%, var(--depth) 50%)', border: '1px solid rgba(255,255,255,0.10)', borderRadius: '10px', boxShadow: '0 4px 16px rgba(0,0,0,0.40), inset 0 1px 0 rgba(255,255,255,0.13)' }}>
              <div style={{ fontSize: '11px', fontFamily: 'var(--font-mono)', color: t.color, fontWeight: 700, marginBottom: '4px' }}>{t.label.toUpperCase()}</div>
              <div style={{ fontSize: '28px', fontWeight: 700, fontFamily: 'var(--font-sans)', color: t.n > 0 ? t.color : 'var(--ink-low)' }}>{t.n}</div>
              <div style={{ fontSize: '11px', color: 'var(--ink-low)', marginTop: '2px' }}>{t.desc}</div>
            </div>
          ))}
        </div>
        <button className="btn-secondary" onClick={onExit}>← Back to question bank</button>
      </div>
    )
  }

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '20px' }}>
      {/* Timer bar */}
      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', padding: '12px 16px', background: 'rgba(0,0,0,0.4)', border: '1px solid var(--rim)', borderRadius: '10px' }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
          <span style={{ fontSize: '12px', color: 'var(--ink-low)' }}>Question {idx + 1}/{questions.length}</span>
          <span style={{ fontSize: '11px', padding: '2px 8px', borderRadius: '999px', background: cc.bg, color: cc.text, border: `1px solid ${cc.border}`, fontFamily: 'var(--font-sans)', fontWeight: 600 }}>{q?.cat}</span>
        </div>
        <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
          <span style={{ fontFamily: 'var(--font-mono)', fontSize: '18px', fontWeight: 700, color: overtime ? 'var(--prime)' : 'var(--prime)' }}>
            {overtime ? '+' : ''}{mins}:{String(secs).padStart(2, '0')}
          </span>
          <button onClick={onExit} className="btn-ghost" style={{ fontSize: '12px' }}>✕ Exit</button>
        </div>
      </div>

      {/* Progress bar */}
      <div style={{ height: '3px', background: 'var(--rim)', borderRadius: '2px' }}>
        <div style={{ height: '100%', width: `${Math.min(100, (elapsed / DURATION) * 100)}%`, background: 'var(--prime)', borderRadius: '2px', transition: 'width 1s linear' }} />
      </div>

      {/* Question */}
      <div style={{ padding: '28px 32px', background: 'var(--depth)', border: `1px solid ${cc.border}`, borderRadius: '12px' }}>
        <p style={{ fontFamily: 'var(--font-sans)', fontSize: '18px', fontWeight: 600, color: 'var(--ink-hi)', lineHeight: 1.5, margin: 0 }}>{q?.q}</p>
      </div>

      {!revealed && q?.whatsTested && (
        <div className="msl-hint" style={{ marginBottom: '-4px' }}>
          <span style={{ fontWeight: 600, color: 'var(--prime)' }}>What's being tested: </span>{q.whatsTested}
        </div>
      )}

      {!revealed ? (
        <div style={{ display: 'flex', gap: '10px' }}>
          <button className="btn-primary" onClick={() => setRevealed(true)}>Reveal answer</button>
          <button className="btn-secondary" onClick={nextQ}>Skip →</button>
        </div>
      ) : (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '14px' }}>
          <div style={{ padding: '20px 24px', background: cc.bg, border: `1px solid ${cc.border}`, borderRadius: '10px' }}>
            {q?.framework && (
              <div style={{ marginBottom: q.answer ? '12px' : 0 }}>
                <div style={{ fontSize: '11px', color: cc.text, textTransform: 'uppercase', letterSpacing: '0.06em', fontFamily: 'var(--font-mono)', marginBottom: '8px' }}>Framework</div>
                <ol style={{ margin: 0, paddingLeft: '18px', display: 'flex', flexDirection: 'column', gap: '5px' }}>
                  {q.framework.map((f, i) => <li key={i} style={{ fontSize: '13px', color: 'var(--ink-mid)', lineHeight: 1.7 }}>{f}</li>)}
                </ol>
              </div>
            )}
            {q?.answer && (
              <div>
                <div style={{ fontSize: '11px', color: cc.text, textTransform: 'uppercase', letterSpacing: '0.06em', fontFamily: 'var(--font-mono)', marginBottom: '8px' }}>Model Answer</div>
                <p style={{ fontSize: '13px', color: 'var(--ink-mid)', lineHeight: 1.75, margin: 0, whiteSpace: 'pre-line' }}>{q.answer}</p>
              </div>
            )}
            {q?.antiPattern && (
              <div style={{ marginTop: '16px', padding: '12px 14px', background: 'rgba(244,63,94,0.06)', border: '1px solid rgba(244,63,94,0.25)', borderRadius: '8px' }}>
                <div style={{ fontSize: '10px', color: 'var(--rose)', fontWeight: 700, letterSpacing: '0.08em', textTransform: 'uppercase', marginBottom: '6px' }}>Don't say this</div>
                <p style={{ fontSize: '12px', color: 'var(--ink-mid)', lineHeight: 1.65, margin: 0 }}>{q.antiPattern}</p>
              </div>
            )}
          </div>

          {/* 4-tier self-assessment */}
          {!tierSelected ? (
            <div style={{ padding: '16px 20px', background: 'rgba(0,0,0,0.3)', border: '1px solid var(--rim)', borderRadius: '10px' }}>
              <div className="section-eyebrow" style={{ marginBottom: '12px' }}>How did you do?</div>
              <div style={{ display: 'flex', flexDirection: 'column', gap: '7px' }}>
                {TIER_LEVELS.map(t => (
                  <button key={t.key}
                    onClick={() => { setTierSelected(t.key); setTierHistory(h => [...h, { id: q.id, tier: t.key }]) }}
                    style={{ display: 'flex', alignItems: 'center', gap: '10px', padding: '8px 14px', background: hoveredTier === t.key ? `${t.color}12` : 'transparent', border: `1px solid ${t.color}20`, borderRadius: '8px', cursor: 'pointer', textAlign: 'left', transition: 'background 0.12s' }}
                    onMouseEnter={() => setHoveredTier(t.key)}
                    onMouseLeave={() => setHoveredTier(null)}>
                    <span style={{ fontFamily: 'var(--font-sans)', fontWeight: 700, fontSize: '12px', color: t.color, minWidth: '52px' }}>{t.label}</span>
                    <span style={{ fontSize: '12px', color: 'var(--ink-mid)' }}>{t.desc}</span>
                  </button>
                ))}
              </div>
            </div>
          ) : (
            <div style={{ display: 'flex', alignItems: 'center', gap: '12px', flexWrap: 'wrap' }}>
              <span style={{ fontSize: '12px', fontFamily: 'var(--font-mono)', color: TIER_LEVELS.find(t => t.key === tierSelected)?.color, fontWeight: 700 }}>
                <CheckMark /> {tierSelected.toUpperCase()}
              </span>
              <button className="btn-primary" onClick={nextQ} disabled={isLast}>
                {isLast ? 'View summary →' : 'Next question →'}
              </button>
            </div>
          )}
        </div>
      )}
    </div>
  )
}

// ─── System Design Judgment ──────────────────────────────────────────────────
const STEP_LABELS = [
  'Step 1 — Clarify objective',
  'Step 2 — Define ML task type',
  'Step 3 — Data pipeline & labels',
  'Step 4 — Feature engineering',
  'Step 5 — Model selection & training',
  'Step 6 — Evaluation & deployment',
]

const DESIGN_SCENARIOS = [
  {
    id: 1,
    brief: 'PM: "Build a model that predicts which users will churn next month."',
    context: 'The team has 2 years of event logs. A gradient boosting model on engagement features is already in training.',
    correct: 2,
    answer: 'The churn label is undefined. Cancellation, 30-day inactivity, and non-renewal produce different label distributions, model behavior, and intervention logic. Training started on an undefined target — everything built on the wrong label is wasted.',
    trap: 'Most people jump to feature engineering — behavioral sequences are clearly valuable. But if the label definition is wrong, the best features in the world produce the wrong model.',
    method: 'Write: "a user is churned if ___ on day ___." Validate the definition with PM and business stakeholders before a single row of training data is touched.',
  },
  {
    id: 2,
    brief: 'PM: "Improve our home feed. Engagement is down 8% QoQ."',
    context: 'The current model optimizes for 7-day click-through rate. The team is planning to add more user features.',
    correct: 0,
    answer: 'Engagement is down but the objective is undefined. CTR, session time, content diversity, and user satisfaction are all "engagement" but require different models with different tradeoffs. Adding features to the wrong objective makes things worse faster.',
    trap: 'Adding more features (Step 4) is the instinctive response. But enriching a model optimizing the wrong objective deepens the problem — possibly optimizing for clickbait or doom-scrolling.',
    method: 'Run a north-star alignment session. Is the goal retention, revenue, or wellbeing? Each implies a different proxy metric and model objective. Then add features.',
  },
  {
    id: 3,
    brief: 'PM: "Our fraud detection model has too many false negatives. It\'s costing $2M/month."',
    context: 'The team has labeled transaction data (0.1% fraud rate). They\'re debating XGBoost vs a neural network.',
    correct: 5,
    answer: 'At 0.1% prevalence, even a 99% accurate model is useless. The critical decision is the operating point on the precision-recall curve — driven by the cost matrix (cost of missed fraud vs cost of blocking legit transactions). Model architecture is a distant second concern.',
    trap: 'Choosing between XGBoost and neural network (Step 5) is debated endlessly here. But both can hit any point on the PR curve — what matters is defining the cost matrix that sets the right threshold.',
    method: 'Define C_FN (cost of missed fraud) and C_FP (cost of blocking a legit transaction). The optimal threshold follows directly from the ratio. Build this into evaluation before touching architecture.',
  },
  {
    id: 4,
    brief: 'PM: "We need a recommendation system. Users aren\'t discovering new items."',
    context: 'The team is planning collaborative filtering on purchase history.',
    correct: 1,
    answer: 'Collaborative filtering on purchases is a pointwise relevance task — it predicts P(purchase | user, item). But discovery requires novelty, not just relevance. CF will surface popular items the user already knows. The task framing is wrong before a line of code is written.',
    trap: 'Jumping straight to collaborative filtering (Step 5) before defining what discovery means. CF optimizes for relevance — it will make the discovery problem worse by surfacing popular items.',
    method: 'Separate recall (candidate generation) from ranking (scoring by a composite of relevance + novelty). Add an explicit diversity term or a re-ranker that penalizes popularity bias.',
  },
  {
    id: 5,
    brief: 'PM: "Flag harmful content before it goes viral. Human moderation is too slow."',
    context: 'The team has 500K labeled examples from human moderators and is ready to train a BERT classifier.',
    correct: 2,
    answer: 'Human moderation labels carry annotation bias — moderators disagree on edge cases across regions, shifts, and cultures. 500K noisy labels produce a model that learns annotator disagreement as signal. A label quality audit before training is the highest-leverage action available.',
    trap: 'Training a BERT classifier (Step 5) seems ready — you have data and a proven architecture. But label noise in content moderation is well-documented. A label audit often reveals 15–20% disagreement on borderline classes.',
    method: 'Run an inter-annotator agreement check (Cohen\'s kappa). For low-agreement classes, create an escalation tier rather than forcing a binary label. Clean 200K labels beat noisy 500K.',
  },
  {
    id: 6,
    brief: 'PM: "Our delivery ETA estimates are too optimistic. Customers complain about late orders."',
    context: 'The team has GPS pings, historical delivery times, and weather data. They\'re deciding between gradient boosting and a sequence model.',
    correct: 0,
    answer: 'The objective metric is undefined. MAE treats a 10-minute overestimate and underestimate identically — but customers hate late arrivals far more than early ones. P90 lateness, asymmetric loss, or a business SLA each lead to different models. Architecture choice is downstream of this decision.',
    trap: 'Gradient boosting vs sequence model (Step 5) is the exciting debate. But both can be trained with symmetric or asymmetric loss — define the loss function first, then pick the architecture that fits it.',
    method: 'Propose an asymmetric loss penalizing underestimates (late arrivals) more heavily. Get PM alignment on an acceptable P90 lateness threshold before touching model architecture.',
  },
  {
    id: 7,
    brief: 'PM: "Our new search ranking model has 15% better NDCG@10 on offline eval. Ready to launch."',
    context: 'The team ran offline evaluation on 3 months of click logs. Conversion is the business metric.',
    correct: 5,
    answer: 'NDCG@10 improved offline but conversion hasn\'t been measured online. Offline-online metric gaps are the most common failure mode in search ranking — position bias in click logs inflates NDCG gains that don\'t transfer to revenue. "Ready to launch" based on offline eval alone is premature.',
    trap: 'A 15% offline improvement looks like a clear win. But search is notorious for offline-online gaps. Shipping without an A/B test burns engineering credibility when conversion doesn\'t move.',
    method: 'Run the new model in shadow mode for one week. Compare predicted ranking vs live ranking on a held-out query set. Canary at 1% traffic before full rollout.',
  },
  {
    id: 8,
    brief: 'PM: "Personalize push notifications to improve re-engagement."',
    context: 'The team has a model predicting P(open | user, notification). They plan to send to the top 20% of users by score.',
    correct: 5,
    answer: 'The deployment strategy ignores notification fatigue and causal effect. P(open) is highest for engaged users who would re-engage anyway — the model is selecting users who don\'t need a push. Without a holdout group, you can\'t measure whether notifications cause engagement or merely correlate with it.',
    trap: 'The model seems technically sound (Step 5 is fine). The mistake is in deployment — top-20% selection maximizes opens but not uplift. This is a deployment and evaluation problem, not a modeling one.',
    method: 'Estimate notification uplift with a PSM or RCT holdout. Target users where P(engage | notification) - P(engage | no notification) is highest — not users with the highest absolute P(open).',
  },
]

function SystemDesignJudgment() {
  const [idx,      setIdx]      = useState(0)
  const [chosen,   setChosen]   = useState(null)
  const [revealed, setRevealed] = useState(false)

  const sc = DESIGN_SCENARIOS[idx]

  function next() {
    setIdx(i => (i + 1) % DESIGN_SCENARIOS.length)
    setChosen(null)
    setRevealed(false)
  }

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '20px' }}>
      <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
        <span style={{ fontSize: '12px', color: 'var(--ink-low)' }}>{idx + 1} / {DESIGN_SCENARIOS.length}</span>
        <div style={{ flex: 1, height: '3px', background: 'var(--rim)', borderRadius: '2px' }}>
          <div style={{ width: `${((idx + 1) / DESIGN_SCENARIOS.length) * 100}%`, height: '100%', background: 'var(--prime)', borderRadius: '2px', transition: 'width 0.3s' }} />
        </div>
      </div>

      <div style={{ background: 'rgba(240,165,0,0.08)', border: '1px solid rgba(240,165,0,0.2)', borderRadius: '12px', padding: '20px 24px' }}>
        <div style={{ fontSize: '10px', color: 'var(--prime)', fontWeight: 600, letterSpacing: '0.08em', textTransform: 'uppercase', marginBottom: '10px' }}>System Brief</div>
        <div style={{ fontSize: '15px', color: 'var(--ink-hi)', fontStyle: 'italic', lineHeight: 1.6, marginBottom: '12px' }}>{sc.brief}</div>
        <div style={{ fontSize: '13px', color: 'var(--ink-mid)', lineHeight: 1.6 }}>{sc.context}</div>
      </div>

      <div style={{ fontSize: '14px', color: 'var(--ink-hi)', fontWeight: 600 }}>Which step of the 6-step framework has the most critical unresolved gap?</div>

      <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
        {STEP_LABELS.map((label, i) => {
          const isChosen  = chosen === i
          const isCorrect = i === sc.correct
          const stateClass = revealed && isCorrect ? ' correct' : (revealed && isChosen && !isCorrect) ? ' wrong' : (!revealed && isChosen) ? ' selected' : ''
          return (
            <button key={i} disabled={revealed} onClick={() => setChosen(i)}
              className={`msl-option-btn${stateClass}`}
              style={{ cursor: revealed ? 'default' : 'pointer', fontWeight: (isChosen || (revealed && isCorrect)) ? 600 : 400 }}>
              {label}
              {revealed && isCorrect && <span style={{ marginLeft: '8px', fontSize: '11px', color: 'var(--mint)' }}>correct</span>}
              {revealed && isChosen && !isCorrect && <span style={{ marginLeft: '8px', fontSize: '11px', color: 'var(--rose)' }}>your pick</span>}
            </button>
          )
        })}
      </div>

      {!revealed && chosen !== null && (
        <button className="btn-primary" onClick={() => setRevealed(true)} style={{ alignSelf: 'flex-start', padding: '10px 20px' }}>Reveal answer</button>
      )}

      {revealed && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
          <div className="msl-reveal-panel">
            <div className="section-eyebrow" style={{ marginBottom: '8px' }}>Why this step</div>
            <div style={{ fontSize: '13px', color: 'var(--ink-hi)', lineHeight: 1.65 }}>{sc.answer}</div>
          </div>
          <div style={{ background: 'rgba(240,165,0,0.08)', border: '1px solid rgba(240,165,0,0.2)', borderRadius: '10px', padding: '16px 20px' }}>
            <div style={{ fontSize: '10px', color: 'var(--ink-low)', fontWeight: 600, letterSpacing: '0.08em', textTransform: 'uppercase', marginBottom: '8px' }}>Common trap</div>
            <div style={{ fontSize: '13px', color: 'var(--ink-hi)', lineHeight: 1.65 }}>{sc.trap}</div>
          </div>
          <div style={{ background: 'rgba(240,165,0,0.08)', border: '1px solid rgba(240,165,0,0.2)', borderRadius: '10px', padding: '16px 20px' }}>
            <div style={{ fontSize: '10px', color: 'var(--prime)', fontWeight: 600, letterSpacing: '0.08em', textTransform: 'uppercase', marginBottom: '8px' }}>Framework move</div>
            <div style={{ fontSize: '13px', color: 'var(--ink-hi)', lineHeight: 1.65 }}>{sc.method}</div>
          </div>
          <button className="btn-primary" onClick={next} style={{ alignSelf: 'flex-start', padding: '10px 20px' }}>
            {idx < DESIGN_SCENARIOS.length - 1 ? 'Next scenario →' : 'Restart →'}
          </button>
        </div>
      )}
    </div>
  )
}

// ─── Main tab ────────────────────────────────────────────────────────────────
export default function InterviewPrepTab({ onNavigate }) {
  const [mode,    setMode]    = useState('bank')   // 'bank' | 'practice' | 'fluency' | 'design' | 'behavioral'
  const [cat,     setCat]     = useState('All')
  const [company, setCompany] = useState('All')
  const [level,   setLevel]   = useState('All')
  const [open,    setOpen]    = useState(null)
  const [search,  setSearch]  = useState('')
  const [, forceUpdate] = useState(0)

  const filtered = useMemo(() => QUESTIONS.filter(q => {
    if (cat !== 'All' && q.cat !== cat) return false
    if (company !== 'All' && q.company !== company) return false
    if (level !== 'All' && q.level !== level) return false
    if (search && !q.q.toLowerCase().includes(search.toLowerCase())) return false
    return true
  }), [cat, company, level, search])

  function shuffle(arr) {
    const a = [...arr]; for (let i = a.length-1; i > 0; i--) { const j = Math.floor(Math.random()*(i+1)); [a[i],a[j]]=[a[j],a[i]] } return a
  }

  if (mode === 'practice') return <TimedPractice questions={shuffle(filtered.length > 0 ? filtered : QUESTIONS)} onExit={() => setMode('bank')} />

  const MODES = [
    { key: 'bank',    label: 'Question Bank' },
    { key: 'practice',label: 'Timed Practice' },
    { key: 'fluency', label: 'Fluency Drills' },
    { key: 'design',  label: 'Design Judgment' },
    { key: 'behavioral', label: 'Behavioral' },
  ]

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '24px' }}>
      {/* Header */}
      <div>
        <h1 style={{ fontFamily: 'var(--font-sans)', fontSize: '28px', fontWeight: 900, letterSpacing: '-0.05em', margin: 0, background: 'linear-gradient(135deg, var(--prime) 0%, var(--ink-hi) 60%)', WebkitBackgroundClip: 'text', WebkitTextFillColor: 'transparent', backgroundClip: 'text', marginBottom: '6px' }}>Interview Prep</h1>
        <p style={{ fontSize: '14px', color: 'var(--ink-mid)', lineHeight: 1.65, maxWidth: '600px', margin: '0 0 4px' }}>
          {QUESTIONS.length} questions across System Design, Features, Evaluation, Spark, Statistics, Trees, SQL, Regression, Architecture, and Coding. Plus 30 fluency drills for weak-to-strong vocabulary.
        </p>
        <p style={{ fontSize: '13px', color: 'var(--ink-low)', lineHeight: 1.5, margin: 0, fontFamily: 'var(--font-sans)', maxWidth: '600px' }}>Browse the bank to scan by topic, run Timed Practice to simulate interview pacing, use Fluency Drills to tighten ML vocabulary, or try Design Judgment for open-ended reasoning questions.</p>
      </div>

      {/* Mode switcher */}
      <div style={{ display: 'flex', gap: '6px', flexWrap: 'wrap', padding: '4px', background: 'rgba(0,0,0,0.3)', border: '1px solid var(--rim)', borderRadius: '10px', width: 'fit-content' }}>
        {MODES.map(m => (
          <button key={m.key} onClick={() => setMode(m.key)}
            style={{ padding: '7px 16px', borderRadius: '7px', border: 'none', cursor: 'pointer', fontSize: '13px', fontFamily: 'var(--font-sans)', fontWeight: 500, transition: 'all 0.15s',
              background: mode === m.key ? 'var(--prime)' : 'transparent',
              color: mode === m.key ? 'var(--void)' : 'var(--ink-mid)' }}>
            {m.label}
          </button>
        ))}
      </div>

      {/* Fluency mode */}
      {mode === 'fluency' && <FluencyDrills />}

      {/* Design Judgment mode */}
      {mode === 'design' && <SystemDesignJudgment />}

      {/* Behavioral Scenarios mode */}
      {mode === 'behavioral' && <BehavioralScenarios />}

      {/* Bank mode */}
      {mode === 'bank' && (
        <>
          {/* Filters */}
          <div style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
            <input value={search} onChange={e => setSearch(e.target.value)} placeholder="Search questions…"
              style={{ width: '100%', maxWidth: '400px' }} type="search" />
            <div style={{ display: 'flex', flexWrap: 'wrap', gap: '6px' }}>
              {CATEGORIES.map(c => <button key={c} onClick={() => setCat(c)} className={`sub-tab ${cat === c ? 'active' : 'inactive'}`} style={{ fontSize: '12px' }}>{c}</button>)}
            </div>
            <div style={{ display: 'flex', flexWrap: 'wrap', gap: '6px' }}>
              {COMPANIES.map(c => <button key={c} onClick={() => setCompany(c)} className={`sub-tab ${company === c ? 'active' : 'inactive'}`} style={{ fontSize: '12px' }}>{c}</button>)}
            </div>
            <div style={{ display: 'flex', flexWrap: 'wrap', gap: '6px' }}>
              {LEVELS.map(c => <button key={c} onClick={() => setLevel(c)} className={`sub-tab ${level === c ? 'active' : 'inactive'}`} style={{ fontSize: '12px' }}>{c}</button>)}
            </div>
          </div>

          <div style={{ fontSize: '12px', color: 'var(--ink-low)' }}>{filtered.length} question{filtered.length !== 1 ? 's' : ''} · click to expand answer</div>

          <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
            {filtered.map(q => {
              const cc = CAT_COLORS[q.cat] || CAT_COLORS['Architecture']
              const isOpen = open === q.id
              return (
                <div key={q.id} className="card" style={{ padding: 0, overflow: 'hidden', cursor: 'pointer', border: isOpen ? `1px solid ${cc.border}` : '1px solid var(--rim)' }}
                  onClick={() => setOpen(isOpen ? null : q.id)}>
                  <div style={{ display: 'flex', alignItems: 'flex-start', gap: '14px', padding: '14px 18px' }}>
                    <span style={{ fontSize: '11px', color: 'var(--ink-ghost)', fontFamily: 'var(--font-mono)', paddingTop: '2px', minWidth: '24px' }}>{String(q.id).padStart(2, '0')}</span>
                    <div style={{ flex: 1, minWidth: 0 }}>
                      <div style={{ display: 'flex', flexWrap: 'wrap', gap: '5px', marginBottom: '6px', alignItems: 'center' }}>
                        <span style={{ fontSize: '10px', fontWeight: 600, padding: '2px 8px', borderRadius: '999px', background: cc.bg, color: cc.text, border: `1px solid ${cc.border}`, fontFamily: 'var(--font-sans)' }}>{q.cat}</span>
                        {q.company !== 'Any' && <span className="badge badge-ghost" style={{ fontSize: '10px' }}>{q.company}</span>}
                        <span className={`badge ${q.level === 'Staff' ? 'badge-rose' : q.level === 'Senior' ? 'badge-ember' : 'badge-ghost'}`} style={{ fontSize: '10px' }}>{q.level}</span>
                      </div>
                      <p style={{ fontSize: '14px', color: 'var(--ink-hi)', lineHeight: 1.6, margin: 0 }}>{q.q}</p>
                    </div>
                    <button
                      onClick={e => { e.stopPropagation(); toggleBookmark('interview', String(q.id), q.q.slice(0,40)); forceUpdate(n => n+1) }}
                      style={{ background: 'none', border: 'none', cursor: 'pointer', fontSize: '14px', padding: '0 4px', color: isBookmarked('interview', String(q.id)) ? 'var(--prime)' : 'var(--ink-ghost)', flexShrink: 0, lineHeight: 1 }}
                      title={isBookmarked('interview', String(q.id)) ? 'Remove bookmark' : 'Bookmark'}
                    >{isBookmarked('interview', String(q.id)) ? <svg width="12" height="14" viewBox="0 0 12 14" fill="currentColor" xmlns="http://www.w3.org/2000/svg"><path d="M2 0.5h8a1 1 0 011 1v11.25l-5-2.917-5 2.917V1.5a1 1 0 011-1z"/></svg> : <svg width="12" height="14" viewBox="0 0 12 14" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" xmlns="http://www.w3.org/2000/svg"><path d="M2 1h8a.5.5 0 01.5.5v11L6 9.75 1.5 12.5V1.5A.5.5 0 012 1z"/></svg>}</button>
                    <span style={{ color: 'var(--ink-low)', fontSize: '13px', paddingTop: '2px', transition: 'transform 0.15s', transform: isOpen ? 'rotate(180deg)' : 'none', flexShrink: 0 }}>▾</span>
                  </div>
                  {isOpen && (
                    <div style={{ borderTop: `1px solid ${cc.border}`, padding: '16px 18px 18px 56px', background: cc.bg }}>
                      {q.whatsTested && (
                        <div className="msl-hint" style={{ marginBottom: '14px' }}>
                          <span style={{ fontWeight: 600, color: 'var(--prime)' }}>What's being tested: </span>{q.whatsTested}
                        </div>
                      )}
                      {q.framework && (
                        <div style={{ marginBottom: q.answer ? '16px' : 0 }}>
                          <div style={{ fontSize: '11px', color: cc.text, fontWeight: 600, textTransform: 'uppercase', letterSpacing: '0.05em', marginBottom: '10px' }}>Framework</div>
                          <ol style={{ margin: 0, paddingLeft: '18px', display: 'flex', flexDirection: 'column', gap: '6px' }}>
                            {q.framework.map((f, i) => <li key={i} style={{ fontSize: '13px', color: 'var(--ink-mid)', lineHeight: 1.7 }}>{f}</li>)}
                          </ol>
                        </div>
                      )}
                      {q.answer && (
                        <div>
                          <div style={{ fontSize: '11px', color: cc.text, fontWeight: 600, textTransform: 'uppercase', letterSpacing: '0.05em', marginBottom: '10px' }}>Model Answer</div>
                          <p style={{ fontSize: '13px', color: 'var(--ink-mid)', lineHeight: 1.75, margin: 0, whiteSpace: 'pre-line' }}>{q.answer}</p>
                        </div>
                      )}
                      {q.antiPattern && (
                        <div style={{ marginTop: '14px', padding: '12px 14px', background: 'rgba(244,63,94,0.06)', border: '1px solid rgba(244,63,94,0.25)', borderRadius: '8px' }}>
                          <div style={{ fontSize: '10px', color: 'var(--rose)', fontWeight: 700, letterSpacing: '0.08em', textTransform: 'uppercase', marginBottom: '6px' }}>Don't say this</div>
                          <p style={{ fontSize: '12px', color: 'var(--ink-mid)', lineHeight: 1.65, margin: 0 }}>{q.antiPattern}</p>
                        </div>
                      )}
                    </div>
                  )}
                </div>
              )
            })}
          </div>
        </>
      )}

      {onNavigate && (
        <div style={{ background: 'var(--prime-bg-light)', border: '1px solid rgba(240,165,0,0.2)', borderRadius: '8px', padding: '12px 16px', display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: '12px', flexWrap: 'wrap', marginTop: '24px' }}>
          <span style={{ fontSize: '13px', color: 'var(--ink-mid)', lineHeight: 1.5 }}>
            Go deeper → Read <strong style={{ color: 'var(--prime)' }}>10 ML Interview Mistakes Even Senior Engineers Make</strong> in Gradient
          </span>
          <button onClick={() => onNavigate('gradient')} style={{ background: 'rgba(240,165,0,0.10)', border: '1px solid rgba(240,165,0,0.3)', borderRadius: '6px', color: 'var(--prime)', fontSize: '12px', fontFamily: 'var(--font-sans)', fontWeight: 500, padding: '6px 14px', cursor: 'pointer', whiteSpace: 'nowrap' }}>
            Read in Gradient →
          </button>
        </div>
      )}
    </div>
  )
}
